(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0023.js"] = [{"id":"poem-981205a1c3d8917bc10cb996","title":"减字木兰花·襄王梦里","author":"黄庭坚","dynasty":"宋","verses":["襄王梦里。","草绿烟深何处是。","宋玉台头。","暮雨朝云几许愁。","飞花漫漫。","不管羁人肠欲断。","春水茫茫。","欲度南陵更断肠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-677","tags":[]},{"id":"poem-98129bc2cabd3929ef52c3f8","title":"闰月三日即事","author":"释居简","dynasty":"宋","verses":["星历新传误，无人重讲明。","日中阴似夜，春半冷如正。","柳欲眠还醒，花犹染不成。","燕归多日了，犹自未闻鶑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-569fd97a-2234-4272-bd3f-1019d6d77207","tags":[]},{"id":"poem-9812ac35d8d845ada0b08316","title":"游仙词三十三首  其一二","author":"王镃","dynasty":"宋","verses":["珊瑚老树百花开，玉色灵泉滴翠崖。","弹罢瑶琴黄鹤至，紫泥湿透藕丝鞋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-497c5319-1a37-461c-b0b1-96027effecdd","tags":[]},{"id":"poem-9824a24f3e8e41e5c1054100","title":"十玄谈（幷序） 玄机","author":"常察","dynasty":"唐","verses":["迢迢空劫勿能收，岂为尘机作系留。","妙体本来无处所，通身何更问（《大正》本、《偈颂》作「有」）纵由？","灵然一句超群象，迥出三乘不假修。","撒手那边诸（《大正》本、《偈颂》作「千」）圣外，回程堪作火中牛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-91000f28-648b-4b36-b3e3-7591d8609f08","tags":[]},{"id":"poem-98253c72427743750504676e","title":"梅花酒","author":"杨景贤","dynasty":"元","verses":["都赖着佛旨，水府内为师，早地上当时，尘世上官司。","那海龙王报救命恩，小和尚说因缘事。","上八年离城市，离城市到龙祠，到龙祠住偌时，住偌时再回之。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7973","tags":[]},{"id":"poem-9846eb6b5ab9b62423fc0aa2","title":"九章·怀沙","author":"屈原","dynasty":"先秦","verses":["滔滔孟夏兮，草木莽莽。","伤怀永哀兮，汩徂南土。","眴兮杳杳，孔静幽默。","郁结纡轸兮，离慜而长鞠。","抚情效志兮，冤屈而自抑。","刓方以为圜兮，常度未替。","易初本迪兮，君子所鄙。","章画志墨兮，前图未改。","内厚质正兮，大人所盛。","巧倕不斲兮，孰察其拨正。","玄文处幽兮，蒙瞍谓之不章。","离娄微睇兮，瞽以为无明。","变白以为黑兮，倒上以为下。","凤皇在笯兮，鸡鹜翔舞。","同糅玉石兮，一概而相量。","夫惟党人之鄙固兮，羌不知余之所臧。","任重载盛兮，陷滞而不济。","怀瑾握瑜兮，穷不知所示。","邑犬之群吠兮，吠所怪也。","非俊疑杰兮，固庸态也。","文质疏内兮，众不知余之异采。","材朴委积兮，莫知余之所有。","重仁袭义兮，谨厚以为丰。","重华不可遌兮，孰知余之从容！","古固有不并兮，岂知其何故也？","汤禹久远兮，邈而不可慕也？","惩违改忿兮，抑心而自强。","离慜而不迁兮，愿志之有像。","进路北次兮，日昧昧其将暮。","舒忧娱哀兮，限之以大故。","乱曰：浩浩沅湘，分流汩兮。","修路幽蔽，道远忽兮。","怀质抱情，独无匹兮。","伯乐既没，骥焉程兮。","民生禀命，各有所错兮。","定心广志，余何所畏惧兮？","曾伤爰哀，永叹喟兮。","世浑浊莫吾知，人心不可谓兮。","知死不可让，愿勿爱兮。","明告君子，吾将以为类兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-17","tags":[]},{"id":"poem-984b8e4264023584e9efdf64","title":"寻纪道士偶会诸叟","author":"李益","dynasty":"唐","verses":["山阴寻道士，暎竹羽衣新。","侍坐双童子，陪游五老人。","水花松下静，坛草雪中春。","见说桃源洞，如今犹避秦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-aa3d4999-dde9-40af-958d-0a79eb4d2171","tags":[]},{"id":"poem-984bd711096be8cd2fd1e667","title":"白府真君","author":"赵杰之","dynasty":"宋","verses":["卓茂当年政术优，治声终不似贤侯。","显幽一致施仁化，庙食中山卒未休。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-f27326f4-9b8d-4727-9bd4-62d785c802b1","tags":[]},{"id":"poem-984e6d56f4660e62880dcfc1","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["蔷薇帘箔，荷花池馆，一点风来香满。","香奁日永，香销宝篆沉烟。","谩有枕欹寒王，扇动齐纨，怎遂得黄香愿？(泪下介)(贴)做甚么？(生介唱)猛然心地热，透香汗，我欲向南窗一醉眠。","(合前)(贴唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5093","tags":[]},{"id":"poem-985380311bc54cd064eb47ff","title":"三台·见梨花初带夜月","author":"万俟咏","dynasty":"宋","verses":["见梨花初带夜月，海棠半含朝雨。","内苑春、不禁过青门，御沟涨、潜通南浦。","东风静、细柳垂金缕。","望凤阙、非烟非雾。","好时代、朝野多欢，遍九陌、太平箫鼓。","乍莺儿百啭断续，燕子飞来飞去。","近绿水、台榭映秋千，斗草聚、双双游女。","饧香更、酒冷踏青路。","会暗识、夭桃朱户。","向晚骤、宝马雕鞍，醉襟惹、乱花飞絮。","正轻寒轻暖漏永，半阴半晴云暮。","禁火天、已是试新妆，岁华到、三分佳处。","清明看、汉宫传蜡炬。","散翠烟、飞入槐府。","敛兵卫、阊阖门开，住传宣、又还休务。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-268","tags":["宋词三百首"]},{"id":"poem-9858c7d9a4d357eb1f4d7ff5","title":"学仙","author":"张籍","dynasty":"唐","verses":["楼观开朱门，树木连房廊。","中有学仙人，少年休谷粮。","高冠如芙蓉，霞月披衣裳。","六时朝上清，佩玉纷铿锵。","自言天老书，秘覆云锦囊。","百年度一人，妄泄有灾殃。","每占有仙相，然后传此方。","先生坐中堂，弟子跪四厢。","金刀截身发，结誓焚灵香。","弟子得其诀，清斋入空房。","守神保元气，动息随天罡。","炉烧丹砂尽，昼夜候火光。","药成既服食，计日乘鸾凰。","虚空无灵应，终岁安所望。","勤劳不能成，疑虑积心肠。","虚羸生疾疹，寿命多夭伤。","身殁惧人见，夜埋山谷傍。","求道慕灵异，不如守寻常。","先王知其非，戒之在国章。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-06cb49fe-1ae7-464b-8b6c-00fa521adf16","tags":[]},{"id":"poem-985f23e515934ba54154c83b","title":"奉送宋中丞使河源","author":"李端","dynasty":"唐","verses":["东周遣戍役，才子欲离群。","部领河源去，悠悠陇水分。","笳声悲塞草，马首渡关云。","辛苦逢炎热，何时及汉军。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-aa6ff7f8-433b-4dc6-b98f-d78991d0b06f","tags":[]},{"id":"poem-985fd0f145312d45853e33dd","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(丑、末)宣限紧，休作等闲。","报国家，忠心似丹。","(旦)稍迟延半晌，稍迟延半晌。","寻思只得些时，面觑尊颜。","子父隔绝，雾阻云拦。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2911","tags":[]},{"id":"poem-986e1e4c0451cf456f8536ac","title":"顾著作宅赋诗","author":"包佶","dynasty":"唐","verses":["几年江海烟霞，乘醉一到京华。","已觉不嫌羊酪，谁能长守兔罝。","脱巾偏招相国，逢竹便认吾家。","各在芸台阁里，烦君日日登车。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7da2608c-26ec-44e8-a87b-2ba1aa566724","tags":[]},{"id":"poem-986f00695e3bc9f8ba25d1ee","title":"挽歌五首 其四","author":"无名氏","dynasty":"唐","verses":["巢阁方瞻[鳯]（风），鸣郊忽酬麟。","六宫悲晏驾，四岳罢来巡。","玺绶传当璧，河山委大臣。","自伤蒲柳质，不得扈龙輴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3240bf79-3118-4887-8f4f-623c58b93857","tags":[]},{"id":"poem-986f14a1b64aa4e1f411d482","title":"戏赠村妇","author":"张祜","dynasty":"唐","verses":["二升酸醋瓦瓶盛，请得姑嫜十日程。","赤黑画眉临水笑，草鞋苞脚逐风行。","黄丝髪乱梳橑紧，青䘢裙高种掠轻。","想得到家相见后，父娘由唤小时名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-64eb21d4-e493-460c-81e8-cf0994ed3401","tags":[]},{"id":"poem-987524f1df3211d22353bdaf","title":"三月初晚晴寄高缙之三首  其三","author":"陈造","dynasty":"宋","verses":["曲栏倚青冥，万井入指顾。","湖光漾明霞，照我凭栏处。","森木倦鸟归，遥空征鸿度。","定知待月人，破竹有奇句。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4301afed-5e4f-4790-ab88-549d3c1cad0e","tags":[]},{"id":"poem-987684fd75596ebdb4c3811b","title":"登圭峰旧隐寄荐福栖白上人","author":"李洞","dynasty":"唐","verses":["返照塔轮边，残霖滴几悬。","夜寒吟病甚，秋健讲声圆。","粟穗干灯焰，苔根浊水泉。","西峰埋藓石，秋月即师禅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-61df8469-edba-4292-852e-8d743861e055","tags":[]},{"id":"poem-987e13528e62e758e440860e","title":"十三日晨起霜晴用定王台韵赋此","author":"张栻","dynasty":"宋","verses":["晴岚开岳镇，云雨断阳台。","日出寒光迥，川平秀色回。","兴随天际鴈，诗寄岭头梅。","盛事它年说，凭君记玉杯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-0e5a6594-5e84-479f-b559-9206d88bc075","tags":[]},{"id":"poem-987fee62e2b45ba9d4b7a801","title":"偈颂（幷序○序为南岳齐己撰） 七十六","author":"居遁","dynasty":"唐","verses":["道死如枯木，波涛岂更违。","时人虽不顾，能歇海盲龟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c6651441-1841-498e-8837-c70ed78b0f2f","tags":["衡山"]},{"id":"poem-98838c07f4689d8f5d489f59","title":"怀智体道人","author":"贯休","dynasty":"唐","verses":["栖碧思吾友，庭莺百啭时。","唯应一处住，方得不相思。","云水淹门阃，春雷在树枝。","平生无限事，不独白云知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-8aee9d96-68d9-4f98-8e8c-7398592228ad","tags":[]},{"id":"poem-98903be794466ce63ff6d645","title":"赠笔工","author":"释居简","dynasty":"宋","verses":["散捉紫毫新脱颖，玄泓渴饮淬锋寒。","将军翰墨场中老，避槊方知夺槊难。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-aac653d9-2d72-456c-b144-c0f6866e0aa3","tags":[]},{"id":"poem-9894f36b66667d9c6101efe5","title":"直甫见示次云乞豫章集数诗偶成二小绝因以自喻  其一","author":"林光朝","dynasty":"宋","verses":["修水佳人白玉栏，花前何似妾容颜。","从来未省伤春意，犹自楼头画远山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-369d4b70-cb1e-4053-b055-bee894790aee","tags":[]},{"id":"poem-9898c34dbbe6b8d7b72412c8","title":"同李太守北池泛舟宴高平郑太守","author":"高适","dynasty":"唐","verses":["每揖龚黄事，还陪李郭舟。","云从四岳起，水向百城流。","幽意随登陟，嘉言即献酬。","乃知缝掖贵，今日对诸侯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-67e52566-31d7-40e8-8ee5-8cb5bbb057f3","tags":[]},{"id":"poem-98a90fa93c403cf997fb9351","title":"赠道人","author":"曹松","dynasty":"唐","verses":["住山因以福为庭，便向山中隐姓名。","阆苑驾将雕羽去，洞天赢得绿毛生。","日边肠胃餐霞火，月里肌肤饮露英。","顾我从来断浮浊，拟驱鸡犬上三清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c1bed828-6a98-40cf-8348-3bab4960fdaf","tags":[]},{"id":"poem-98aa5bd03d7879280544197b","title":"宿悟空寺赠僧","author":"鲍溶","dynasty":"唐","verses":["劳者谣烛蛾，致身何营营。","雪山本师在，心地如镜清。","往与本师别，人间买浮名。","朝光畏不久，内火烧人情。","迷路喜为远，宿留化人城。","前心宛如此，了了随静生。","维持薝卜花，却与前心行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4d7e4c3f-2852-4e6a-b36b-18e75b7c1b59","tags":[]},{"id":"poem-98abf6bf8a70cb560b281c32","title":"宿西山凌云观","author":"李翔","dynasty":"唐","verses":["掩映真居不易求，自惊何路到蓬丘。","庭心月近石坛古，海面风微山殿秋。","控鹤岭高星半隔，伏龙岗转水分流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4781fa5e-6ec8-48cc-a4c2-157bb3e7dfb6","tags":[]},{"id":"poem-98b00f4364fa1092421fa4cd","title":"晚次巴陵","author":"李端","dynasty":"唐","verses":["雪后柳条新，巴陵城下人。","烹鱼邀水客，载酒奠山神。","云去低斑竹，波回动白苹。","不堪逢楚老，日暮正江春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-5bf914dc-5c7f-4d9f-abe7-b5b2e1b10186","tags":[]},{"id":"poem-98b23adafa146835c43ef118","title":"晚登瀼上堂","author":"杜甫","dynasty":"唐","verses":["故跻瀼岸高，颇免崖石拥。","开襟野堂豁，系马林花动。","雉堞粉如云，山田麦无垅。","春气晚更生，江流静犹涌。","四序婴我怀，群盗久相踵。","黎民困逆节，天子渴垂拱。","所思注东北，深峡转修耸。","衰老自成病，郎官未为冗。","凄其望吕葛，不复梦周孔。","济世数向时，斯人各枯冢。","楚星南天黑，蜀月西雾重。","安得随鸟翎，迫此惧将恐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6b5a9040-28e2-4179-8a83-b211cd4b0341","tags":[]},{"id":"poem-98b5b763cdda5d51e8dfa315","title":"寄别","author":"杨凭","dynasty":"唐","verses":["晚烟洲雾共苍苍，河雁惊飞不作行。","廻斾转舟行数里，歌声犹自逐清湘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-bd7b2791-2af0-4dbb-8ad0-36686e015ab9","tags":[]},{"id":"poem-98c1963ae628d08a6eeaba52","title":"宫词  其七四","author":"张公庠","dynasty":"宋","verses":["自古诗人咏具瞻，官仪丞相独尊严。","三衙扣杖一声喏，只是朱衣略揭帘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-46390de4-1a4c-4344-9b9e-99a60672e79c","tags":[]},{"id":"poem-98c5960c44a886086bbfc2b5","title":"乾元中寓居同谷县作歌七首 一","author":"杜甫","dynasty":"唐","verses":["有客有客字子美，白头乱发垂过耳。","岁拾橡栗随狙公，天寒日暮山谷里。","中原无书归不得，手脚冻皴皮肉死。","鸣呼一歌兮歌已哀，悲风为我从天来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ae8396b9-da62-4b1b-9c75-580ff9bfdda3","tags":[]},{"id":"poem-98cc4d8dcbda9dc38a0e0f17","title":"刘展下判官相招以诗答之","author":"崔峒","dynasty":"唐","verses":["国有非常宠，家承异姓勋。","背恩慙皎日，不义若浮云。","但使忠贞在，甘从玉石焚。","窜身如有地，梦寐见明君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-3abc38e4-f4ce-4a03-8cff-368a950c86e6","tags":[]},{"id":"poem-98d1d3de80112d4b4b352041","title":"留上李右相","author":"高适","dynasty":"唐","verses":["风俗登淳古，君臣挹大庭。","深沈谋九德，密勿契千龄。","独立调元气，清心豁窅冥。","本枝连帝系，长策冠生灵。","傅说明殷道，萧何律汉刑。","钧衡持国柄，柱石总朝经。","隐轸江山藻，氛氲鼎鼐铭。","兴中皆白雪，身外即丹青。","江海呼穷鸟，诗书问聚萤。","吹嘘成羽翼，提握动芳馨。","倚伏悲还笑，栖迟醉复醒。","恩荣初就列，含育忝宵形。","有窃丘山惠，无时枕席宁。","壮心瞻落景，生事感浮萍。","莫以才难用，终期善易听。","未为门下客，徒谢少微星。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d0a388eb-dd3d-4735-aacc-392ff3a2bed1","tags":[]},{"id":"poem-98dbfe4c66c7737cb7206415","title":"七娘子","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(老旦上)孩儿美貌体天然，似洛浦神仙，荏苒芳年。","(旦)凛烈寒风垂幕，喜得晴明天气。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8817","tags":[]},{"id":"poem-98debf0dfdb5689d550b425f","title":"临江仙引·渡口、向晚","author":"柳永","dynasty":"宋","verses":["渡口、向晚，乘瘦马、陟平冈。","西郊又送秋光。","对暮山横翠，衬残叶飘黄。","凭高念远，素景楚天，无处不凄凉。","香闺别来无信息，云愁雨恨难忘。","指帝城归路，但烟水茫茫。","凝情望断泪眼，尽日独立斜阳。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-226","tags":[]},{"id":"poem-98eecae2965e058f679ade70","title":"七谏·初放","author":"东方朔","dynasty":"汉","verses":["平生于国兮，长于原野。","言语讷譅兮，又无彊辅。","浅智褊能兮，闻见又寡。","数言便事兮，见怨门下。","王不察其长利兮，卒见弃乎原野。","伏念思过兮，无可改者。","群众成朋兮，上浸以惑。","巧佞在前兮，贤者灭息。","尧、舜圣已没兮，孰为忠直？","高山崔巍兮，水流汤汤。","死日将至兮，与麋鹿同坑。","块兮鞠，当道宿，举世皆然兮，余将谁告？","斥逐鸿鹄兮，近习鸱枭，斩伐橘柚兮，列树苦桃。","便娟之修竹兮，寄生乎江潭。","上葳蕤而防露兮，下泠泠而来风。","孰知其不合兮，若竹柏之异心。","往者不可及兮，来者不可待。","悠悠苍天兮，莫我振理。","窃怨君之不寤兮，吾独死而后已。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-30","tags":[]},{"id":"poem-98f432206b87df80c30e0c94","title":"浄照律师葬母冢上生芝十二茎关子长𬙂倚松饶德操赋诗后九十余载余亦赋","author":"释居简","dynasty":"宋","verses":["尸罗为源孝为根，一根岂止十二茎。","沉香亭北烂缯绮，浪花浮蘂争欣荣。","喑喑泪滴冢上土，只有天知此心苦。","地灵荐瑞天不靳，付与千人万人覩。","诗人史法语不浮，旌孝笔端回万牛。","紫芝不老亦不槁，两公之诗更新好。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-466b1aee-00da-43fb-9e83-aa43e1210057","tags":[]},{"id":"poem-98f687516892c42549f3de53","title":"好事近·对竹擘吟笺","author":"史浩","dynasty":"宋","verses":["对竹擘吟笺，正是赏梅时节。","便把这些清致，作东湖三绝。","帝家金鼎待调羹，何似且休折。","却爱玉楼清弄，褪霏霏香雪。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-150","tags":[]},{"id":"poem-98fae96b60662ae98708b669","title":"上平江徐侍郎十绝句  其六","author":"曾协","dynasty":"宋","verses":["绕郭旧称家十万，朝天常恨驿三千。","而今已是繁华倍，更觉旌麾近日边。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-7354b20e-86f7-47b9-a5cf-ecd515726fc6","tags":[]},{"id":"poem-98fe46ff79ef9dd70dc76b0f","title":"天仙子·渌水亭秋夜","author":"纳兰性德","dynasty":"清","verses":["水浴凉蟾风入袂，鱼鳞蹙损金波碎。","好天良夜酒盈尊，心自醉，愁难睡。","西风月落城乌起。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-168","tags":[]},{"id":"poem-992ad54fd90af70c885ad3be","title":"吊草堂禅师","author":"李洞","dynasty":"唐","verses":["杖屦疑师在，房关四壁蛬。","贮缾经腊水，响塔隔山钟。","乳鸽沿苔井，斋猿散雪峰。","如何不见性，倚徧寺前松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b1556fc7-e7f6-40d4-a2a5-fc62fd7720b7","tags":[]},{"id":"poem-992c2db2cb831cbefde9f3d7","title":"送韦判官得雨中山","author":"卢纶","dynasty":"唐","verses":["前峰后岭碧蒙蒙，草拥惊泉树带风。","人语马嘶听不得，更堪长路在云中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-95551421-c7e5-4b3b-9524-2b16e2adfffb","tags":[]},{"id":"poem-992ea83195c2bc55285910e4","title":"白纻辞二首 一","author":"崔国辅","dynasty":"唐","verses":["洛阳梨花落如霰，河阳桃叶生复齐。","坐惜玉楼春欲尽，红绵粉絮裛妆啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-78a84f2a-d55a-4449-8d62-65f0affd23ec","tags":[]},{"id":"poem-9930694724f136a963b6260b","title":"忆平泉杂咏 忆春雨","author":"李德裕","dynasty":"唐","verses":["春鸠鸣野树，细雨入池塘。","潭上花微落，溪边草更长。","梳风白鹭起，拂水彩鸳翔。","最羡归飞燕，年年在故乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-5db47599-0db5-4a4f-90f4-9f76b8d1036e","tags":[]},{"id":"poem-9934068797aa2c0e0e8b3479","title":"灵隠方丈新阁接泗洲妙崧毁之","author":"释居简","dynasty":"宋","verses":["乡来屋老拊岩棱，欲上看山谢不能。","衡跨半天开复道，直从平地到危层。","上方近听婴儿语，前塔遥分竺寺灯。","昨晚乱云收急雨，凭高如望海涛崩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-6ecbd04a-9660-49ec-a572-5e8baa589061","tags":[]},{"id":"poem-99356388f5aad56821b3fb35","title":"夜发军中","author":"李益","dynasty":"唐","verses":["边马枥上惊，雄劒匣中鸣。","半夜军书致，匈奴寇六城。","中坚分暗阵，太乙起神兵。","出没风云合，苍黄豺虎争。","今日边庭战，缘赏不缘名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-7a6b502b-cb9c-497a-9d54-9ba097e0ea2d","tags":[]},{"id":"poem-99385719c359f7bd3e792bc7","title":"经古墓","author":"熊孺登","dynasty":"唐","verses":["碑折松枯山火烧，夜台从闭不曾朝。","那将逝者比流水，流水东流逢上潮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-f680d452-eee6-47f9-91e5-58d07bff29de","tags":[]},{"id":"poem-993e9392c7d21e8573155f0e","title":"和主司王起","author":"崔轩","dynasty":"唐","verses":["满朝朱紫半门生，新榜劳人又得名。","国器旧知收片玉，朝宗转觉集登瀛。","同升翰苑三年美，继入花源九族荣。","共仰莲峰听雪唱，欲赓仙曲意怔营。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e6b06eaa-d8c0-41d9-b404-8a0d3f57dcf1","tags":[]},{"id":"poem-993f0de99844cd573cb8a15c","title":"赠因长老","author":"释居简","dynasty":"宋","verses":["金猊铁脊铁腰顽，趁鼠随狐屈折难。","因是正因须自信，避些炎热耐些寒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-4a4ca97f-dc44-4898-a8aa-6c339a0db332","tags":[]},{"id":"poem-994b1d081bfc002b88fd35f0","title":"水调歌头·小筑百年计","author":"毛并","dynasty":"宋","verses":["小筑百年计，雅志几人成。","乱山深处，烟雨面面对萦青。","巾屦方安吾土，花木仍供真赏，邻有阮嵇生。","岁月抛身外，尘事更无营。","鸟知归，云出岫，两忘情。","从渠华屋，回首烟草吊颓倾。","何似生涯才足，敧枕南窗北牖，醉梦落樵声。","更喜濯缨处，门外一江清。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-604","tags":[]},{"id":"poem-994c790afcd653b4f0cca1bd","title":"上元侍宴","author":"苏轼","dynasty":"宋","verses":["淡月疏星绕建章，仙风吹下御炉香。","侍臣鹄立通明殿，一朵红云捧玉皇。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-上元侍宴","tags":[]},{"id":"poem-994ebf8495ff2571c046be8f","title":"长门怨","author":"张乔","dynasty":"唐","verses":["御泉长绕凤皇楼，自是恩波别处流。","闲揲舞衣归未得，夜来砧杵六宫秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f3e2ecc5-b67a-4498-ab42-781a23bb2c27","tags":[]},{"id":"poem-9951e66cdab140109db2a8b9","title":"偈五首  其三","author":"释士珪","dynasty":"宋","verses":["一叶落，天下秋，欲穷千里目，更上一层楼。","一尘起，大地收，嘉州打大像，陕府灌铁牛。","久旱簷头句，桥流水不流。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-ae15f883-2d8f-4b33-8ac3-ba6aa5dfedb1","tags":[]},{"id":"poem-995fefd0eb1303e1e98ff87c","title":"颂古三十二首  其二三","author":"释明辩","dynasty":"唐","verses":["打起黄莺儿，莫教枝上啼。","几回惊妾梦，不得到辽西。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-228c87f2-092b-411b-9029-c5454cc2cb1c","tags":["怀人","五言绝句","闺怨","唐诗三百首"]},{"id":"poem-99613cbc16811aad0e2fc674","title":"代陈季若上张帅  其三","author":"林光朝","dynasty":"宋","verses":["晋公当日只平淮，何事都人尚尔怀。","客有昌黎韩吏部，独将大笔扫苍苔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-52a277c3-b009-4b07-b566-e8e8cb5cf726","tags":[]},{"id":"poem-9961a75994a067fed99d3096","title":"郊庙歌辞 五郊乐章 白郊迎神","author":"不详","dynasty":"唐","verses":["序移玉律，节应金商。","天严杀气，吹警秋方。","槱燎既积，稷奠并芳。","乐以迎奏，庶降神光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-460e1cd1-cc6c-494e-a20f-5197be96f3d7","tags":[]},{"id":"poem-99787f4f7bcad0e7facb70f7","title":"宿僧舍","author":"赵嘏","dynasty":"唐","verses":["高僧夜滴芙蓉漏，远客窗含杨柳风。","何处相逢话心地，月明身在磬声中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2ebc6009-94a1-4c43-ba9e-654d3b6a5608","tags":[]},{"id":"poem-997fbb7f66e2c34c731f9d0c","title":"夏日即事","author":"吕从庆","dynasty":"唐","verses":["结伴居山寺，超然见白云。","境闲堪问道，客雅好论文。","坐石惟看奕，行田或课耘。","夜来尘俗语，不向梦中闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0e1e85ad-7f3c-4559-8a73-f2db17287670","tags":[]},{"id":"poem-99801d93edc5406cc1cbf8df","title":"夏日  其二","author":"宋伯仁","dynasty":"宋","verses":["泓泓圆碧漾新荷，猎猎斜风颤绿莎。","农事正忙三月后，野田齐唱插秧歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-d0ecbcdb-57e3-44f1-bf2a-4e44387e401e","tags":[]},{"id":"poem-998c0c846793a7f169cdce72","title":"重阳四首 三","author":"司空图","dynasty":"唐","verses":["青娥懒唱无衣换，黄菊新开乞酒难。","长有长亭惆怅事，隔河更得对凭栏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-88003232-fd34-465e-a554-def43a11403d","tags":[]},{"id":"poem-998c78aee26047b641664613","title":"题北村六首  其四","author":"张载","dynasty":"宋","verses":["风泉盈耳鬓斑斑，林下幽窗对万山。","妇子职修簟食足，病身何幸亦安闲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-99ab87d2-4d4e-4505-8847-e6f1227fa997","tags":[]},{"id":"poem-9991c5fe4f924411e98e4ffe","title":"在灵峰时为后生造偈（题拟）","author":"皎然","dynasty":"唐","verses":["素面相呈犹不识，更添脂粉竞鬪看。","这里若论玄与实，与吾如隔万重山。","（均见《祖堂集》卷十。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6625f6f5-2fc6-4061-b014-7a0fd3d0a2bc","tags":[]},{"id":"poem-9992579e4bb7ccf5e693a30d","title":"江神子・江城子·破瓜年纪柳腰身","author":"谢薖","dynasty":"宋","verses":["破瓜年纪柳腰身。","懒精神。","带羞瞋。","手把江梅，冰雪斗清新。","不向鸦儿飞处著。","留乞与，眼中人。","水精船里酒粼粼。","皱香茵。","驻行云。","舞罢歌馀，花困不胜春。","问著些儿心底事，才靥笑，又眉颦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-971","tags":[]},{"id":"poem-999a7e8f868030eba83b46e4","title":"登兖州城楼","author":"杜甫","dynasty":"唐","verses":["东郡趋庭日，南楼纵目初。","浮云连海岳，平野入青徐。","孤嶂秦碑在，荒城鲁殿余。","从来多古意，临眺独踌躇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-eabe74ad-1a13-481d-92e4-9207a59396c5","tags":[]},{"id":"poem-99a26e0cae122404f73dae15","title":"九真山净居寺谒无碍上人","author":"沈佺期","dynasty":"唐","verses":["大士生天竺，分身化日南。","人中出烦恼，山下即伽蓝。","小涧香为刹，危峰石作龛。","候禅青鸽乳，窥讲白猿参。","藤爱云间壁，花怜石下潭。","泉行幽供好，林挂浴衣堪。","弟子哀无识，医王惜未谈。","机疑闻不二，蒙昧即朝三。","欲究因缘理，聊宽放弃慙。","超然虎溪夕，双树下虚岚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-09ce8658-5174-43e6-a693-f58a7ef8dd32","tags":[]},{"id":"poem-99a55b62c6179fa11a0c37cf","title":"九叹·逢纷","author":"刘向","dynasty":"汉","verses":["伊伯庸之末胄兮，谅皇直之屈原。","云余肇祖于高阳兮，惟楚怀之婵连。","原生受命于贞节兮，鸿永路有嘉名。","齐名字于天地兮，并光明于列星。","吸精粹而吐氛浊兮，横邪世而不取容。","行叩诚而不阿兮，遂见排而逢谗。","后听虚而黜实兮，不吾理而顺情。","肠愤悁而含怒兮，志迁蹇而左倾。","心戃慌其不我与兮，躬速速其不吾亲。","辞灵修而陨志兮，吟泽畔之江滨。","椒桂罗以颠覆兮，有竭信而归诚。","谗夫蔼蔼而漫著兮，曷其不舒予情？","始结言于庙堂兮，信中涂而叛之。","怀兰蕙与衡芷兮，行中野而散之。","声哀哀而怀高丘兮，心愁愁而思旧邦。","愿承闲而自恃兮，径淫曀而道壅。","颜霉黧以沮败兮，精越裂而衰耄。","裳襜襜而含风兮，衣纳纳而掩露。","赴江湘之湍流兮，顺波凑而下降。","徐徘徊于山阿兮，飘风来之汹汹。","驰余车兮玄石，步余马兮洞庭。","平明发兮苍梧，夕投宿兮石城。","芙蓉盖而菱华车兮，紫贝阙而玉堂。","薜荔饰而陆离荐兮，鱼鳞衣而白蜺裳。","登逢龙而下陨兮，违故都之漫漫。","思南郢之旧俗兮，肠一夕而九运。","扬流波之潢潢兮，体溶溶而东回。","心怊怅以永思兮，意晻晻而日颓。","白露纷以涂涂兮，秋风浏以萧萧。","身永流而不还兮，魂长逝而常愁。","叹曰：譬彼流水纷扬磕兮，波逢汹涌𣸣壅滂兮。","揄扬涤荡飘流陨往触崟石兮，龙卬脟圈缭戾宛转阻相薄兮，遭纷逢凶蹇离尤兮，垂文扬采遗将来兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-47","tags":[]},{"id":"poem-99a640e6c9f1f9a8c7133831","title":"江边道士","author":"贯休","dynasty":"唐","verses":["独住大江滨，不知何代人。","药罏生紫气，肌肉似红银。","酒酽竹屋[烂]，符收山鬼仁。","何妨将我去，一看武陵春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d60762fd-8b7e-41fb-922c-c1e2bc5e70f9","tags":[]},{"id":"poem-99a77563b67a5376f30de216","title":"海棠春·落红片片浑如雾","author":"纳兰性德","dynasty":"清","verses":["落红片片浑如雾，不教更觅桃源路。","香径晚风寒，月在花飞处。","蔷薇影暗空凝贮。","任碧飐轻衫萦住。","惊起早栖鸦，飞过秋千去。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-76","tags":[]},{"id":"poem-99aadb20514d3f54a5976621","title":"口号  其一","author":"刘跂","dynasty":"宋","verses":["孟仲争秋毒热新，自今三指算归旬。","已判明月隔千里，可对茱萸少一人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-81c33985-1573-4aa4-8746-c1bf714b6357","tags":[]},{"id":"poem-99b394c23b06f491cc659a64","title":"减字木兰花·珠帘乍见","author":"王之望","dynasty":"宋","verses":["珠帘乍见。","云雨无踪空有怨。","锦字新词。","青鸟衔来恼暗期。","桃溪得路。","直到仙家留客处。","今日东邻。","远忆当年窥宋人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-486","tags":[]},{"id":"poem-99c21e57743faa038df43d70","title":"寄冯尉","author":"陈造","dynasty":"宋","verses":["我遵兔径西山麓，荆棘钩衣尘瞇目。","怜渠此地费流光，君亦风餐并露宿。","遗蝗蹢躅无地皮，田禾蚕食犹孑遗。","洊饥可念劳可忍，君自坦坦人怜之。","繁昌乱山仅容鏬，一一到我马蹄下。","南村吃饭宿北村，罢极凭诗写悲唶。","即今不作劳者歌，器识视我几倍过。","脱身箠楚吾已多，简书趋走子如何。","皇家猎隽张云罗，长安知己肩相摩。","五云深深护台阁，缥缈群僊依碧落。","即看郭振起通泉，应笑卑陬郡文学。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-39f92781-b80a-441c-a862-5deb475c373c","tags":[]},{"id":"poem-99c8b2e142e0986d71cb1a39","title":"平江太守李宝谟移漕荆湘  其二","author":"释居简","dynasty":"宋","verses":["不据喉衿地，如何展壮图。","一麾移使节，三楚即全吴。","鹦鹉春常早，貔貅信必孚。","不知坐上客，更有祢生无。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-50f821f0-d15c-45ec-8211-7f37227b5a32","tags":[]},{"id":"poem-99cdf20ef4c19c9029f983b3","title":"山云","author":"曾协","dynasty":"宋","verses":["自耸干霄势，应怜望岁心。","试将肤寸泽，来作济时霖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-653f22b7-dde3-426d-b007-ba8dd1ed097a","tags":[]},{"id":"poem-99d28e867d508cc2062c48da","title":"漫兴","author":"杜甫","dynasty":"唐","verses":["糁径杨花铺白毡，点溪荷叶叠青钱。","笋根稚子无人见，沙上凫雏傍母眠。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-漫興","tags":[]},{"id":"poem-99e046bfe9bc48e4e017dfa6","title":"伏读三月六日内禅诏书及传将士牓檄慨王室之艰危悯生灵之涂炭悼前策之不从恨奸回之误国感愤有作聊以述怀四首  其四","author":"李纲","dynasty":"宋","verses":["建炎虚席待经纶，恩赐宸章宝墨新。","学际天人何敢尔，忠开金石庶当仁。","孔明得主规模壮，陆贽离朝谤讟频。","今日追思惭至意，御书重执泪盈巾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-ccff016c-40c9-4411-a95a-e45b5058ae15","tags":[]},{"id":"poem-99ef31b09d6c240aa5f29c08","title":"送贺监归四明应制","author":"李林甫","dynasty":"唐","verses":["挂冠知止足，岂独汉疏贤。","入道求真侣，辞恩访列仙。","睿文含日月，宸翰动云烟。","鹤驾吴乡远，遥遥南斗边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-5b18b761-a4fe-4ccb-b1e2-978566267463","tags":[]},{"id":"poem-99fe0d2b566b0ca05b38dd43","title":"赋帘","author":"太宗皇帝","dynasty":"唐","verses":["参差垂玉阙，舒卷映兰宫。","珠光摇素月，竹影乱清风。","彩散银钩上，文斜桂户中。","惟当杂罗绮，相与媚房栊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-48bb657b-455d-4dd1-a38a-4312d39968fd","tags":[]},{"id":"poem-99fe3c6205883679b76d2c66","title":"露","author":"徐夤","dynasty":"唐","verses":["鹤鸣先警雁来天，洗竹沾花处处鲜。","散彩几当蝉饮际，凝光宜对蚌胎前。","朝垂苑草烟犹重，夜滴宫槐月正圆。","怵惕与霜同降日，苹蘩思荐独凄然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-5d6ae932-1ab4-4689-bf8a-279b4a398ad0","tags":[]},{"id":"poem-9a0e06e76382565e6541a80c","title":"狂题十八首 三","author":"司空图","dynasty":"唐","verses":["交疎自古戒言深，肝胆徒倾致铄金。","不是史迁书与说，谁知孤负李陵心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-327c574e-005d-4b9e-94cd-9411f8e8b68a","tags":[]},{"id":"poem-9a1598ba989d7d1a8af8d7cb","title":"古意论交","author":"李咸用","dynasty":"唐","verses":["择友如淘金，沙尽不得宝。","结交如干银，产竭不成道。","我生四十年，相识苦草草。","多为势利朋，少有岁寒操。","通财能几何，闻善宁相告。","茫然同夜行，中路自不保。","常恐管鲍情，参差忽终老。","今来既见君，青天无片云。","语直瑟弦急，行高山桂芬。","约我为交友，不觉心醺醺。","见义必许死，临危当指囷。","无令后世士，重广孝标文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c4b59c44-5d20-4657-8230-20936edb9367","tags":[]},{"id":"poem-9a17071926f887984827ba1d","title":"七夕","author":"沈佺期","dynasty":"唐","verses":["秋近雁行稀，天高鹊夜飞。","妆成应懒织，今夕渡河归。","月皎宜穿线，风轻得曝衣。","来时不可觉，神验有光辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-04d92f40-d412-4eb5-ab64-d58aa0a779c6","tags":[]},{"id":"poem-9a17291348c73ab9d4781b77","title":"瑞龙吟·章台路","author":"周邦彦","dynasty":"宋","verses":["章台路。","还见褪粉梅梢，试花桃树。","坊陌人家，定巢燕子，归来旧处。","暗凝伫。","因念个人痴小，乍窥门户。","侵晨浅约宫黄，障风映袖，盈盈笑语。","前度刘郎重到，访邻寻里，同时歌舞。","唯有旧家秋娘，声价如故。","吟笺赋笔，犹记燕台句。","知谁伴，名园露饮，东城闲步。","事与孤鸿去。","探春尽是，伤离意绪。","官柳低金缕。","归骑晚，纤纤池塘飞雨。","断肠院落，一帘风絮。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-223","tags":["宋词三百首"]},{"id":"poem-9a35d255f8f569495a1d0899","title":"冷泉亭","author":"林稹","dynasty":"宋","verses":["一泓清可沁诗脾，冷暖年来只自知。","流出西湖载歌舞，回头不似在山时。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-冷泉亭","tags":[]},{"id":"poem-9a36039d4497e5a9a800cef4","title":"上宋使君","author":"贯休","dynasty":"唐","verses":["折桂文如锦，分忧力若春。","位高空倚命，诗妙古无人。","有感禾争熟，无私吏尽贫。","野人如有幸，应得见陶钧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-cfb2a2fd-38b6-4c07-a1df-63ab004ec2ce","tags":[]},{"id":"poem-9a3dc9f11824c82e7f46382d","title":"书匡山老僧庵","author":"贯休","dynasty":"唐","verses":["筼筜红实好鸟语，银髯瘦僧貌如祖。","香烟蒙蒙衣上聚，冥心缥缈入铁圄。","白麏作梦枕藤屦，东峰山媪贡瓜乳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-b2da42c3-3266-4126-84f4-d4a5334b1ab0","tags":["庐山"]},{"id":"poem-9a42140a433eabb512fe9034","title":"寄前黄州窦使君","author":"赵嘏","dynasty":"唐","verses":["池上笙歌寂不闻，楼中愁杀碧虚云。","玉壶凝尽重重泪，寄与风流旧使君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-df71e847-2c43-4330-93b6-d9746cc9ce74","tags":[]},{"id":"poem-9a4296aa1b832c20445d4ee7","title":"偶作五首 三","author":"贯休","dynasty":"唐","verses":["孰云我轻薄，石头如何唤作玉。","孰云我是非，随邪逐恶又争得。","古人终不事悠悠，一言道合死即休。","岂不见大鹏点翼盖十洲，是何之物鸣啾啾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-5f08a3dd-01f6-46b5-908c-3bfd21e509da","tags":[]},{"id":"poem-9a42ae1901b5a521a7bb1180","title":"同刘晃喜雨","author":"明皇帝","dynasty":"唐","verses":["节变寒初尽，时和气已春。","繁云先合寸，膏雨自依旬。","飒飒飞平野，霏霏静暗尘。","悬知花叶意，朝夕望中新。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-865bf66e-c1ad-4fee-8ab0-45876065155a","tags":[]},{"id":"poem-9a4b525e6a4adccff448e118","title":"添撰享太庙乐章 文宗庙奏","author":"张连","dynasty":"唐","verses":["赫尔昭代，显应元亨。","祥符史牒，德振文明。","风调雨顺，海晏河清。","应延大宝，千秋化成。","（同前）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-235ee47e-f1da-4064-ae77-17b3b7f8f27e","tags":[]},{"id":"poem-9a4e383e5dd08c252b6689ae","title":"赠王先生","author":"赵嘏","dynasty":"唐","verses":["太一真人隐翠霞，早年曾降蔡经家。","羽衣使者峭于鹤，鸟爪侍娘飘若花。","九鼎栏干归马齿，三山窕窈步云涯。","时因弟子偷灵药，散落人间驻物华。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-228f838e-18e4-4983-a185-57c93643867f","tags":[]},{"id":"poem-9a4e712ba5be86e51f16afac","title":"·","author":"周匡物","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ee1b1897-e793-43c7-9c7b-991a418af440","tags":[]},{"id":"poem-9a612bcfaa4ef357170d3067","title":"长安晓望寄程补阙","author":"司空曙","dynasty":"唐","verses":["迢遰山河拥帝京，参差宫殿接云平。","风吹晓漏经长乐，柳带晴烟出禁城。","天净笙歌临路发，日高车马隔尘行。","独有浅才甘未达，多慙名在鲁诸生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-59da8f38-abd3-4af3-b549-7b9ef4aec01f","tags":[]},{"id":"poem-9a6c3b1349191b64055c9a64","title":"芭蕉茶送伯承伯承赋诗三章次韵  其三","author":"张栻","dynasty":"宋","verses":["春去云藏岳麓，梅黄雨涨昭潭。","政尔倚栏无那，一瓯唤起清谈。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-fdcb99e9-be52-4064-977b-8c07e4afeeaa","tags":[]},{"id":"poem-9a72bcc88b2f17b4d1ad879f","title":"小重山·鞭凤骖鸾自斗杓","author":"李弥逊","dynasty":"宋","verses":["鞭凤骖鸾自斗杓。","老君亲抱送，下层霄。","人间仙李占春饶。","千秋里，松月伴吹箫。","故国水云遥。","谪仙丹荔熟，剥红绡。","南山影转卧金蕉。","倾寒绿，眉寿比山高。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-47","tags":[]},{"id":"poem-9a81c8b246af6dee4b3c1a9f","title":"励学吟","author":"智闲","dynasty":"唐","verses":["满口语，无处说，明明向道人（一作「人道」）不决。","急著力，勤咬囓，无常到来救不彻。","口里话（一作「语」），暗嗟（一作「瑳」）切，快磨古锥净挑揭。","理尽觉，自护持，此生事，吾（一作「终」）不说，玄旨（一作「学」）求他古老吟，禅学须穷心影绝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0ea48d03-1043-4468-9569-9b6e9fe1443a","tags":[]},{"id":"poem-9a8d21c55ca08c7726cb051b","title":"郊庙歌辞 享太庙乐章 象德舞","author":"段文昌","dynasty":"唐","verses":["肃肃清庙，登显至德。","泽周八荒，兵定四极。","生物咸遂，群盗灭息。","明圣钦承，子孙千亿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-24daec53-cf05-46fb-bfac-051e9eb4b8ce","tags":[]},{"id":"poem-9a8e2181641ff9d11f47024c","title":"入衡州","author":"杜甫","dynasty":"唐","verses":["兵革自久远，兴衰看帝王。","汉仪甚照耀，胡马何猖狂。","老将一失律，清边生战场。","君臣忍瑕垢，河岳空金汤。","重镇如割据，轻权绝纪纲。","军州体不一，宽猛性所将。","嗟彼苦节士，素于圆凿方。","寡妻从为郡，兀者安堵墙。","凋弊惜邦本，哀矜存事常。","旌麾非其任，府库实过防。","恕己独在此，多忧增内伤。","偏裨限酒肉，卒伍单衣裳。","元恶迷是似，聚谋泄康庄。","竟流帐下血，大降湖南殃。","烈火发中夜，高烟焦上苍。","至今分粟帛，杀气吹沅湘。","福善理颠倒，明征天莽茫。","销魂避飞镝，累足穿豺狼。","隐忍枳棘刺，迁延胝趼疮。","远归儿侍侧，犹乳女在旁。","久客幸脱免，暮年慙激昴。","萧条向水陆，汩没随鱼商。","报主身已老，入朝病见妨。","悠悠委薄俗，郁郁回刚肠。","参错走洲渚，舂容转林篁。","片帆左郴岸，通郭前衡阳。","华表云鸟埤，名园花草香。","旗亭壮邑屋，烽橹蟠城隍。","中有古刺史，盛才冠岩廓。","扶颠待柱石，独坐飞风霜。","昨者间琼树，高谈随羽觞。","无论再缱绻，己是安苍黄。","剧孟七国畏，马卿四赋良。","门阑苏生在，勇锐白起强。","问罪富形势，凯歌悬否臧。","氛埃期必埽，蚊蚋焉能当。","橘井旧地宅，仙山引舟航。","此行厌暑雨，厥土闻清凉。","诸舅剖符近，开缄书札光。","频繁命屡及，磊落字百行。","江总外家养，谢安乘兴长。","下流匪珠玉，择木羞鸾皇。","我师嵇叔夜，世贤张子房。","柴荆寄乐土，鹏路观翱翔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2e0f6fa4-0e8b-449e-bb5d-0ab704403d37","tags":[]},{"id":"poem-9a9414ddc61afb188653bad9","title":"人日","author":"林滋","dynasty":"唐","verses":["春辉新入碧烟开，芳院初将穆景来。","共向花前图瑞胜，试看池上动轻苔。","林香半落沾罗幌，蕙色微含近酒桮。","闻道宸游方命赏，应随恩赉喜昭回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b3c9c567-cd90-4a43-b10c-9e1769ed0ee0","tags":[]},{"id":"poem-9a987c92cc3d6bcc4c8443e6","title":"范真传侍御累有寄因奉酬十首 九","author":"鲍溶","dynasty":"唐","verses":["萋萋巫峡云，楚客莫留恩。","岁久晋阳道，谁能向太原。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a1a249ad-546d-4e0f-92aa-ad45b5843466","tags":[]},{"id":"poem-9aa1fadb532c0fd9c75dbee4","title":"绝句漫兴","author":"杜甫","dynasty":"唐","verses":["肠断春江欲尽头，杖藜徐步立芳洲。","颠狂柳絮随风舞，轻薄桃花逐水流。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-絕句漫興","tags":[]},{"id":"poem-9aa691ab8e35cbe3fb6f0010","title":"减字浣溪沙・浣溪沙·楼角初销一缕霞","author":"贺铸","dynasty":"宋","verses":["楼角初销一缕霞。","淡黄杨柳暗栖鸦。","玉人和月摘梅花。","笑拈粉香归洞户，更垂帘幕护窗纱。","东风寒似夜来些。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-102","tags":["宋词三百首"]},{"id":"poem-9aa8e8a8998e52023a6ac1ec","title":"句","author":"章嶰","dynasty":"唐","verses":["闻说静中偏爱竹，自看疎密种秋烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9a62ca4f-054a-4cd0-94c7-33f6f6ff0584","tags":[]},{"id":"poem-9aae52612fa5d8885f29549f","title":"莺啼序","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(贴)光阴迅速如电掣，断送了多少豪杰。","遇良辰自宜调燮，且把闲闷抛撇。","进履袜欢看妇仪，炷宝鼎对天答谢。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8327","tags":[]},{"id":"poem-9aafdc2fcde71a8e000451e2","title":"边城听角","author":"李咸用","dynasty":"唐","verses":["戍楼鸣画角，寒露滴金枪。","细引云成阵，高催雁著行。","唤回边将梦，吹薄晓蟾光。","未遂终军志，何劳思故乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-79d30b12-c3a7-4985-aac1-066f56fa52dd","tags":[]},{"id":"poem-9ab047fe5f1a3c0f09943f36","title":"送韩绛归淮南寄韩绰先辈","author":"赵嘏","dynasty":"唐","verses":["岛上花枝系钓船，隋家宫畔水连天。","江帆自落鸟飞外，月观静依春色边。","门巷草生车辙在，朝廷恩及雁行联。","相逢且问昭州事，曾鼓庄盆对逝川。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c6b1ba77-fee7-4750-a37e-42f0676f1e66","tags":[]},{"id":"poem-9ac0f08a6464cba4d503fae4","title":"古栢","author":"李洞","dynasty":"唐","verses":["手植知何代，年齐偃盖松。","结根生别树，吹子落邻峰。","古干经龙嗅，高烟过雁冲。","可佳繁叶尽，声不碍秋钟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8582267f-f885-4180-9db3-5eb53f5eeb68","tags":[]},{"id":"poem-9ac14f1ab7eee85d5589fe08","title":"鹤冲天·黄金榜上","author":"柳永","dynasty":"宋","verses":["黄金榜上。","偶失龙头望。","明代暂遗贤，如何向。","未遂风云便，争不恣狂荡。","何须论得丧。","才子词人，自是白衣卿相。","烟花巷陌，依约丹青屏障。","幸有意中人，堪寻访。","且恁偎红翠，风流事、平生畅。","青春都一饷。","忍把浮名，换了浅斟低唱。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-242","tags":[]},{"id":"poem-9ac613ac9cddbf57d454dd76","title":"千秋岁·苑边花外","author":"黄庭坚","dynasty":"宋","verses":["苑边花外。","记得同朝退。","飞骑轧，鸣珂碎。","齐歌云绕扇，赵舞风回带。","岩鼓断，杯盘狼藉犹相对。","洒泪谁能会。","醉卧藤阴盖。","人已去，词空在。","兔园高宴悄，虎观英游改。","重感慨，波涛万顷珠沈海。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-813","tags":[]},{"id":"poem-9ac669ba6bae3f8888d57aa2","title":"同颜使君真卿李侍御萼游法华寺登凤翅山望太湖","author":"皎然","dynasty":"唐","verses":["双峰开凤翅，秀出南湖州。","地势抱郊树，山威增郡楼。","正逢周柱史，来会鲁诸侯。","缓步凌彩蒨，清铙发飕飗。","披云得灵境，拂石临芳洲。","积翠遥空碧，含风广泽秋。","萧辰资丽思，高论惊精修。","何似钟山集，[征]文及惠休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-144e8b40-7119-4952-9e37-fde527ad7fb1","tags":["太湖"]},{"id":"poem-9ad7ab4b091d9dfbfd705eb0","title":"犯朝","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["你如今便回，道张老的道与蔡伯喈。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5242","tags":[]},{"id":"poem-9ada0c423fcfecc90c80dc61","title":"自鹅城乘舟至河源风雨日作江流湍激以寸步进感叹有作","author":"李纲","dynasty":"宋","verses":["榜舟溯回溪，夏潦适川涨。","惊湍激怒澜，怪石立异状。","篙师巧为计，巨细施石上。","噪呼集众力，进寸退寻丈。","峥嵘三数峰，竟日不离望。","乃知势不便，智力未足仗。","我行极江海，幸免鱼腹葬。","书生妙言辞，过谓神所相。","及兹困沟渎，更觉水石壮。","翻思泛沧溟，千里才一饷。","岂惟小中州，端欲簉昆阆。","斯游不可忘，临风默惆怅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d6d63f9d-ae4b-46bd-92bb-7fe7833750c7","tags":[]},{"id":"poem-9adb915024c7daf2aa8b2b0f","title":"遣兴五首 四","author":"杜甫","dynasty":"唐","verses":["蓬生非无根，漂荡随高风。","天寒落万里，不复归本丛。","客子念故宅，三年门巷空。","怅望但烽火，戎车满关东。","生涯能几何，常在羁旅中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cf5404fd-70f0-47b7-a4a8-8a2a7fb671c4","tags":[]},{"id":"poem-9ae153d0cdcfb16bcf8abfb5","title":"东郊","author":"韦应物","dynasty":"唐","verses":["吏舍跼终年，出郊旷清曙。","杨柳散和风，青山澹吾虑。","依丛适自憩，缘涧还复去。","微雨霭芳原，春鸠鸣何处？乐幽心屡止，遵事迹犹遽。","终罢斯结庐，慕陶真可庶。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3e0e1d96-c249-47c4-b16d-4d91dd6e7cce","tags":["唐诗三百首","春天","生活"]},{"id":"poem-9aecc4e311c036578f671041","title":"望远行·碧砌花光照眼","author":"李璟","dynasty":"五代","verses":["碧砌花光照眼明，朱扉长日镇长扃。","馀寒欲去梦难成，炉香烟冷自亭亭。","辽阳月、秣陵砧，不传消息但传情。","黄金台下忽然惊，征人归日二毛生！"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-1","tags":[]},{"id":"poem-9af21dbb4d5bfa31ae741622","title":"酒泉子·钿匣舞鸾","author":"毛熙震","dynasty":"五代","verses":["钿匣舞鸾，隐映艳红修碧。","月梳斜，云鬓腻，粉香寒。","晓花微敛轻呵展，袅钗金燕软。","日初升，帘半卷，对妆残。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-9","tags":[]},{"id":"poem-9af7dc58f636883b8f80bbce","title":"上元日二首 一","author":"文宗皇帝","dynasty":"唐","verses":["上元高会集群仙，心斋何事欲祈年。","丹诚傥彻玉帝座，且共吾人庆大田。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6edbac82-339f-45d9-908d-89dd67f941e5","tags":[]},{"id":"poem-9afc67f5d4d57f3542a04ec1","title":"句","author":"灵业","dynasty":"唐","verses":["洞中仙草严冬绿，江外灵山腊月青。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-33ba807b-ab65-498e-93f6-e1ed11818966","tags":[]},{"id":"poem-9b0038edc70c11214e814100","title":"和坂领客对月思乡之作","author":"王孝廉","dynasty":"唐","verses":["寂寂朱明夜，团团白月轮。","几山明影彻，万象水天新。","弃妾看生怅，羁情对动神。","谁云千里隔，能照两乡人。","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c7faa2e2-6f32-47e4-bb18-717f07b7ccc8","tags":[]},{"id":"poem-9b02d535ec9a8e88426762f5","title":"往体  其二","author":"赵崇鉘","dynasty":"宋","verses":["皓彩青云端，飞光落溟渤。","浑河与清沚，同受明月魄。","勿以清浊殊，天光本无隔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-7b0360d2-9509-46c0-b059-2ee7d1b86959","tags":[]},{"id":"poem-9b039cbd38ddad89a795cc73","title":"白鼍鸣","author":"张籍","dynasty":"唐","verses":["天欲雨，有东风，南谿白鼍鸣窟中。","六月人家井无水，夜闻鼍声人尽起。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-eaf535f0-d599-4356-b69d-2ad5622e018f","tags":[]},{"id":"poem-9b07348fefc04a43b730d189","title":"青门引・青门饮·乍暖还轻冷","author":"张先","dynasty":"宋","verses":["乍暖还轻冷。","风雨晚来方定。","庭轩寂寞近清明，残花中酒，又是去年病。","楼头画角风吹醒。","入夜重门静。","那堪更被明月，隔墙送过秋千影。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-158","tags":["宋词三百首"]},{"id":"poem-9b12c5696a0005d0ea0a588c","title":"鹅鸭满渡船","author":"无名氏《张协状元》","dynasty":"元","verses":["论妾家豪贵，又岂得随人去。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2706","tags":[]},{"id":"poem-9b15f957455a0e5fd446d28f","title":"气出唱 其三","author":"曹操","dynasty":"汉","verses":["游君山，甚为真。","崔嵬砟硌，尔自为神。","乃到王母台，金阶玉为堂，芝草生殿旁。","东西厢，客满堂。","主人当行觞，坐者长寿遽何央。","长乐甫始宜孙子。","常愿主人增年，与天相守。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-11","tags":[]},{"id":"poem-9b2b38541ab7833b0ea95d3b","title":"满庭芳·北苑春风","author":"黄庭坚","dynasty":"宋","verses":["北苑春风，方圭圆璧，万里名动京关。","碎身粉骨，功合上凌烟。","尊俎风流战胜，降春睡、开拓愁边。","纤纤捧，研膏溅乳，金缕鹧鸪斑。","相如，虽病渴，一觞一咏，宾有群贤。","为扶起灯前，醉玉颓山。","搜搅心中万卷，还倾动、三峡词源。","归来晚，文君未寝，相对小窗前。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-652","tags":[]},{"id":"poem-9b2b7240c615c878d8f3a0da","title":"清歌儿","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(生作醉上)三杯酒万事和气，又何妨每日沉醉。","思量孙二太无知，伊来害我，我又如何饶你？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1725","tags":[]},{"id":"poem-9b30c7faf1ea58c99cc1695a","title":"鸡黍","author":"米芾","dynasty":"宋","verses":["鸡黍招要意已真，后堂许到转相亲。","巧裁花竹岂多地，浄扫轩窗无一尘。","倾倒不知情话密，衰𬯎深畏酒行频。","落花一夜成疏迹，风雨还增客恨新。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-e63b96e8-0dda-4106-9543-f10e7871ca9b","tags":[]},{"id":"poem-9b360a009c8c571d2d3a2785","title":"春宿左省","author":"杜甫","dynasty":"唐","verses":["花隐掖垣暮，啾啾栖鸟过。","星临万户动，月傍九霄多。","不寝听金钥，因风想玉坷。","明朝有封事，数问夜如何？"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-春宿左省","tags":[]},{"id":"poem-9b37cfe4f5db1bbe9578355f","title":"浣溪沙·莲漏三声烛半条","author":"纳兰性德","dynasty":"清","verses":["莲漏三声烛半条，杏花微雨湿红绡。","那将红豆记无聊，春色己看浓似酒，归期安得信如潮。","离魂入夜倩谁招。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-48","tags":[]},{"id":"poem-9b3bf6bfae150aa275d53348","title":"椶拂子","author":"杜甫","dynasty":"唐","verses":["椶拂且薄陋，岂知身效能。","不堪代白羽，有足除苍蝇。","荧荧金错刀，擢擢朱丝蝇。","非独颜色好，亦用顾盼称。","吾老抱疾病，家贫卧炎蒸。","咂肤倦扑灭，赖尔甘服膺。","物微世竞弃，义在谁肯征。","三岁清秋至，未敢阙缄藤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-704494b5-291d-4f04-a07c-ac2a0c754edc","tags":[]},{"id":"poem-9b3e8c2c088398d130127a30","title":"浣溪沙·马上凝情忆旧游","author":"张泌","dynasty":"五代","verses":["马上凝情忆旧游，照花淹竹小溪流，钿筝罗幕玉搔头。","早是出门长带月，可堪分袂又经秋，晚风斜日不胜愁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-28","tags":[]},{"id":"poem-9b553986bb6e7ae74885d958","title":"夜游宫·人去西楼雁杳","author":"吴文英","dynasty":"宋","verses":["人去西楼雁杳。","叙别梦、扬州一觉。","云澹星疏楚山晓。","听啼乌，立河桥，话未了。","雨外蛩声早。","细织就、霜丝多少。","说与萧娘未知道。","向长安，对秋灯，几人老。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-84","tags":["宋词三百首"]},{"id":"poem-9b59f1bab630b5aa0772ccbe","title":"一寸金·州夹苍崖","author":"周邦彦","dynasty":"宋","verses":["州夹苍崖，下枕江山是城郭。","望海霞接日，红翻水面，晴风吹草，青摇山脚。","波暖凫鹥作。","沙痕退、夜潮正落。","疏林外、一点炊烟，渡口参差正寥廓。","自叹劳生，经年何事，京华信漂泊。","念渚蒲汀柳，空归闲梦，风轮雨楫，终辜前约。","情景牵心眼，流连处、利名易薄。","回头谢、冶叶倡条，便入渔钓乐。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-455","tags":[]},{"id":"poem-9b5bff09d4c6359fed920e4d","title":"句","author":"周存孺","dynasty":"唐","verses":["指下黄金星未曙，七条弦上夜乌啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8b933994-767b-4a3e-8b70-67b4c32cdb92","tags":[]},{"id":"poem-9b61e8689ad511ace8a92573","title":"郊庙歌辞 享太庙乐章 永和","author":"张说","dynasty":"唐","verses":["眇嘉乐，授灵爽。","感若来，思如往。","休气散，回风上。","返寂寞，还惚恍。","怀灵驾，结空想。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e70176f2-53b1-4dbe-963c-ef6fc9e3e64d","tags":[]},{"id":"poem-9b671b04005384f0905ed305","title":"奉酬韦滁州寄示","author":"杨凌","dynasty":"唐","verses":["淮扬为郡暇，坐惜流芳歇。","散怀累榭风，清暑澄潭月。","陪燕辞三楚，戒途绵百越。","非当远别离，雅奏何由发。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2502eef1-d7b2-4d3d-b4b8-ada2d713b03d","tags":[]},{"id":"poem-9b674809e53b3247d5be4a22","title":"塞下曲","author":"高适","dynasty":"唐","verses":["君不见芳树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟守空闺。","独宿自然堪下泪，况复时闻鸟夜啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1ba275a5-93d8-4d90-9367-7192e01dae10","tags":[]},{"id":"poem-9b7c20dc2bfd06dbee9fb011","title":"从军","author":"刘庭琦","dynasty":"唐","verses":["朔风吹寒塞，胡沙千万里。","阵云出岱山，孤月生海水。","决胜方求敌，衔恩本轻死。","萧萧牧马鸣，中夜拔劒起。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-1d108c7f-8c11-48b0-98d0-315baf79b9e6","tags":["泰山"]},{"id":"poem-9b80697aa389dd33d5ca3342","title":"玉楼春·燕鸿过后春归去","author":"欧阳修","dynasty":"宋","verses":["燕鸿过后春归去。","细算浮生千万绪。","来如春梦几多时，去似朝云无觅处。","闻琴解神仙侣。","挽断罗衣留不住。","劝君莫作独醒人，烂醉花间应有数。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-174","tags":["宋词三百首"]},{"id":"poem-9b856f68079b239cb810657f","title":"湖外送何崇入阁","author":"裴说","dynasty":"唐","verses":["因诗相识久，忽此告临途。","便是有船发，也须容市沽。","精吟五个字，稳泛两重湖。","长短逢公道，清名振帝都。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-0b710d4a-a537-4ac6-96fd-c327adbfbfb1","tags":[]},{"id":"poem-9b8b4bebf6774b1d569cbc0b","title":"天仙子·梦觉云屏依旧空","author":"韦庄","dynasty":"五代","verses":["梦觉云屏依旧空，杜鹃声咽隔帘栊，玉郎薄幸去无踪。","一日日，恨重重，泪界莲腮两线红。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-10","tags":[]},{"id":"poem-9b8bf8d3ef2b8d2857a9dc8d","title":"入江西境先寄诸季二首  其二","author":"李纲","dynasty":"宋","verses":["征途诘屈避兵戈，叹息劳生可若何。","却把蘧庐作安宅，毎闻铙鼓輙悲歌。","候门稚子鹤立久，浮海先生霜鬓多。","可惜光阴四寒暑，只于来往与销磨。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6abaf1cc-f0ad-47f2-b75f-ddae3cff5fc0","tags":[]},{"id":"poem-9b9f27deccf2eeaa4ee84495","title":"偈","author":"智晖","dynasty":"唐","verses":["我有一间舍，父母为修盖。","住来八十年，近来觉损坏。","早拟移住（《五灯会元》作「别」）处，事涉有憎爱。","待他摧毁时，彼此无相碍。","（见《景德传灯录》卷二十、《五灯会元》卷十三。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-471b4145-59f8-458c-91c3-47993c61073a","tags":[]},{"id":"poem-9ba0c565be0b92a54df3e279","title":"·","author":"温翁念","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-683e6c19-0951-4e06-abc9-2d55a4c4a098","tags":[]},{"id":"poem-9ba939a95a34ff135709144b","title":"满庭芳·琼馆烟轻","author":"黄裳","dynasty":"宋","verses":["琼馆烟轻，银河风细，玉桥云锁方开。","晓虹千丈，宛转下天来。","人在水精宫里，行乐处、锦绣成堆。","仍相问，人间天上，何处有蓬莱。","徘徊。","追往事，征南巧架，傅野怀才。","谩石驱东海，沙合龙台。","好是乐成初宴，红牙碎、声隐晴雷。","江天晚，游人未散，莫放隼旟回。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-622","tags":[]},{"id":"poem-9baa8517071f23d5b686ff89","title":"普天乐","author":"施惠《幽闺记》","dynasty":"元","verses":["(小旦上)我那哥哥。","叫得我气全无，哭得我声难语。","只教我两头来往到千百步。","兄安在？妾是何如？真个是逆旅穷途。","哥哥，须念我，念我爹娘身故，须是一蒂一瓜儿和女，怎割得断兄妹肠肚，将奴闪下在这里？进无门，退也还又无所。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2946","tags":[]},{"id":"poem-9bb36814a69b91bb06ab3925","title":"春秋战国门 臧孙","author":"周昙","dynasty":"唐","verses":["诸孟憎吾似犬狞，贤臧哭孟倍伤情。","季孙爱我如甘疾，疾足亡身药故宁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-449a8c03-8fcb-410f-b7ca-390ed2602d12","tags":[]},{"id":"poem-9bb4956eba6147d3d3f6dc2f","title":"送崇教大师回天台","author":"阮思道","dynasty":"宋","verses":["碧云高价彻天涯，珪璧清无一点瑕。","双阙再承新雨露，三吴重赏旧烟霞。","水轩散味朝贤句，松院分尝御府茶。","闻说赤城终未见，画图何日寄京华。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-80d09c20-f024-481d-8130-9738886f4c12","tags":[]},{"id":"poem-9bb66ff31007ecd1146e5d58","title":"元日无衣冠入朝寄皇甫拾遗冉从弟补阙纾","author":"李嘉祐","dynasty":"唐","verses":["伏奏随廉使，周行外冗员。","白髭空受岁，丹陛不朝天。","秉烛千官去，垂帘一室眠。","羡君青琐里，并冕入炉烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-fbbc6828-0b3a-4640-a1c9-04223b560134","tags":[]},{"id":"poem-9bb8644665697fcf2c194716","title":"生查子·短焰剔残花","author":"纳兰性德","dynasty":"清","verses":["短焰剔残花，夜久边声寂。","倦舞却闻鸡，暗觉青绫湿。","天水接冥蒙，一角西南白。","欲渡浣花溪，远梦轻无力。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-11","tags":[]},{"id":"poem-9bbd881ee56b21515b0d5432","title":"越调/斗鹌鹑","author":"杨景贤","dynasty":"元","verses":["看了些日月盈亏，山河变迁。","灌口把威施，天涯将姓显。","郭压直把皂鹰擎，金头奴将细狗牵。","背着弓弩，挟着弹丸。","濯锦江头，连云栈边。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4525","tags":[]},{"id":"poem-9bc36e4c5a377eb4c8f52732","title":"留别故人","author":"李端","dynasty":"唐","verses":["此别不可道，此心当语谁。","春风灞水上，饮马桃花时。","误作好文士，祗应游宦迟。","留书下朝客，我有故山期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-f66715b5-7e80-4014-acb6-6bed68d6a4f4","tags":[]},{"id":"poem-9bc826d9ab1a282c2c39527c","title":"旅宿","author":"杜牧","dynasty":"唐","verses":["旅馆无良伴，凝情自悄然。","寒灯思旧事，断鴈警愁眠。","远梦归侵晓，家书到隔年。","湘江好烟月，门系钓鱼船。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-200fe9fa-0221-4123-86de-4d63ce9d3daf","tags":["唐诗三百首","羁旅","思乡","五言律诗"]},{"id":"poem-9bcd27a4ead3c4b55e12626e","title":"方广道中半岭少憩","author":"张栻","dynasty":"宋","verses":["半岭篮舆小驻肩，眼中已觉渺云烟。","山头更尽无穷境，非是人间别有天。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-083dcce9-ef0f-4729-acd6-5af964ef9946","tags":[]},{"id":"poem-9bd014cb785c64648ec6a053","title":"答人问仁者安仁","author":"林光朝","dynasty":"宋","verses":["千年古道万年堤，老牯循循不解迷。","牧子不知何处在，乱山荒草鹧鸪啼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-01b29a58-a8e7-4992-817f-bb72c10d3586","tags":[]},{"id":"poem-9bd09b9802311d920269f7b4","title":"次韵答路监岳","author":"陈造","dynasty":"宋","verses":["房陵水秀山崛奇，政与路子昌其诗。","临风启缄诵杰句，狂酲病卧闻楚辞。","阴阳闭纵坎其鼓，年年凟神为旸雨。","所嗟坐衙未暖席，已有疲民相告语。","买牲酾酒方热中，霈然一雨千里同。","雨足便晴夏田好，麦秋决可收全功。","与民父天免衔恤，更因欢喜忘肺疾。","雄篇良佩君记存，联翩古调仍唐律。","人才高下渊视天，貂不易续私自怜。","侧理漫草腮漫托，缠声鹿鸣媲林乐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-2a347ac2-01f2-463c-8801-6d7b1614eb70","tags":[]},{"id":"poem-9be65cdb1a3aa15d71468632","title":"齐天乐·碧纱窗外黄鹂语","author":"方千里","dynasty":"宋","verses":["碧纱窗外黄鹂语，声声似愁春晚。","岸柳飘绵，庭花堕雪，惟有平芜如剪。","重门尚掩。","看风动疏帘，浪铺湘簟。","暗想前欢，旧游心事寄诗卷。","鳞鸿音信未睹，梦魂寻访后，关山又隔无限。","客馆愁思，天涯倦迹，几许良宵展转。","闲情意远。","记密阁深闺，绣衾罗荐。","睡起无人，料应眉黛敛。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-529","tags":[]},{"id":"poem-9be74d4ef38e81d863e1f942","title":"菩萨蛮·等闲将度三春景","author":"李珣","dynasty":"五代","verses":["等闲将度三春景，帘垂碧砌参差影。","曲槛日初斜，杜鹃啼落花。","恨君容易处，又话潇湘去。","凝思倚屏山，泪流红脸斑。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-44","tags":[]},{"id":"poem-9bf66adb383b36190c8ab939","title":"昔昔盐二十首 花飞桃李蹊","author":"赵嘏","dynasty":"唐","verses":["远期难可托，桃李自依依。","花径无容迹，戎裘未下机。","随风开又落，度日扫还飞。","欲折枝枝赠，那知归不归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5c6cf3ab-1dcb-445f-b3b2-300ff32f67ae","tags":[]},{"id":"poem-9bff41b6d9b9c3b523fb4990","title":"次韵李西美舍人见寄二首  其二","author":"李纲","dynasty":"宋","verses":["几年离索渴微言，敢意髙车过我门。","暂解轩中徐孺榻，谩开坐上孔融樽。","羡君感慨犹能饮，顾我衰迟已抱孙。","杞梓楩楠委崖谷，上章端欲叩天阍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-96fcd9b1-67e7-42ea-be7e-ea8983ef3afd","tags":[]},{"id":"poem-9c0eaca733e6365b2dc265f4","title":"绿意・疏影·碧圆自洁","author":"张炎","dynasty":"宋","verses":["碧圆自洁。","向浅洲远渚，亭亭清绝。","犹有遗簪，不展秋心，能卷几多炎热。","鸳鸯密语同倾盖，且莫与、浣纱人说。","恐怨歌、忽断花风，碎却翠云千叠。","回首当年汉舞，怕飞去、谩皱留仙裙折。","恋恋青衫，犹染枯香，还叹鬓丝飘雪。","盘心清露如铅水，又一夜、西风吹折。","喜静看、匹练秋光，倒泻半湖明月。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-61","tags":["宋词三百首"]},{"id":"poem-9c0ff6007641ddec63f2f3e7","title":"绮霞峰","author":"陈岩","dynasty":"宋","verses":["欲识晴岚态度奇，直须待到夕阳时。","回光倒影山如染，状出余霞散绮诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-3fa87ece-2a6f-4e4d-9ef9-890a90798383","tags":[]},{"id":"poem-9c203b5b0e82acb17ce07133","title":"送季言弟还锡山省先垅四首  其一","author":"李纲","dynasty":"宋","verses":["四年谪去远桑梓，万里归来纷甲兵。","却恨此身方抱病，扫坟不与汝同行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6ff0ce45-cf2b-426f-8cbf-b3f59d3806e5","tags":[]},{"id":"poem-9c20d662ee9a0607e26936c9","title":"恩赦放还集句先寄乡中弟姪三首  其三","author":"刘跂","dynasty":"宋","verses":["闲思往事似前身，羞见黄花无数新。","我家孤姪在海浦，遍插茱萸少一人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-330374f0-04f2-4cd1-a801-58de1458adbf","tags":[]},{"id":"poem-9c223ef8289b474c993ee2b6","title":"山居四感 吟蛩","author":"李纲","dynasty":"宋","verses":["月露凄清湿草根，寒蛩偏向夜深闻。","随时感气成悲怨，不是来销逐客魂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c8d7a875-1a4c-4747-ad67-e728adc56871","tags":[]},{"id":"poem-9c38233cd6b790272833bf2d","title":"谢尹绿坡见访","author":"王镃","dynasty":"宋","verses":["棕鞋闲踏软红尘，道眼青山认得真。","不是江湖相识者，谁来泉石访幽人。","夜寒草屋三更雨，心事梨花一片春。","莫笑家风太枯淡，地垆温酒话逃秦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-0c36188e-35d9-419d-8cf5-d28bc3978907","tags":[]},{"id":"poem-9c3906bfe9de96cd94e3a678","title":"苏武庙","author":"温庭筠","dynasty":"唐","verses":["苏武魂销汉使前，古祠高树两茫然。","云边雁断胡天月，陇上羊归塞草烟。","廻日楼台非甲帐，去时冠劒是丁年。","茂陵不见封侯印，空向秋波哭逝川。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-cae8a893-7ae6-4824-b4c5-eada730b075f","tags":["唐诗三百首","隋・唐・五代","七言律诗","写人","凭吊古迹","赞颂"]},{"id":"poem-9c3bcd871f0290ce2d18787e","title":"赠梁教授","author":"陈造","dynasty":"宋","verses":["梁侯藿菽芼山雌，冷坐欲试菁莪诗。","嗣圣急贤饥渴似，项背趣召君得辞。","九门方悬帝尧鼓，久旱可无傅岩雨。","几听言议得韬韫，了知它日酬所语。","人言才俊当居中，可使流落吾辈同。","邓禹旧补文学掾，萧何不书野战功。","民庸国计当惠恤，和扁之侧无废疾。","会看同沐一台春，底用更试三尺律。","生齿所戴共此天，杞国过忧吾绝怜。","八柱如亏迟君托，未应诗酒私所乐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5c6cb5ad-6e74-4feb-a16d-fd646542e1ce","tags":[]},{"id":"poem-9c414d4bff316cdb61264fc8","title":"乌夜啼·鸾镜愁添眉黛","author":"李石","dynasty":"宋","verses":["鸾镜愁添眉黛，罗裙瘦减腰肢。","一回见了一回病，弹指误佳期。","醉里懵腾泪洗，梦中著摸魂飞。","一春多少闲风雨，亭院落花时。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-257","tags":[]},{"id":"poem-9c41e47739a2bd6366f15ab2","title":"采莲词","author":"张潮","dynasty":"唐","verses":["朝出沙头日正红，晚来云起半江中。","赖逢邻女曾相识，并著莲舟不畏风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-127c8d97-6aa4-4bfe-bbb8-b73e6c984cee","tags":[]},{"id":"poem-9c46ff99a536930db9342b3d","title":"颂古三十一首  其一二","author":"释安永","dynasty":"宋","verses":["臭口未开经万劫，丝毫才犯铁轮随。","雨散云收明月夜，反动江波说向谁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-076ebda6-07ff-4e6a-9b15-f501b11cb03f","tags":[]},{"id":"poem-9c757a5abb71697ef02e9e83","title":"游长宁公主流杯池二十五首 六","author":"上官昭容","dynasty":"唐","verses":["清波汹涌，碧树冥蒙。","莫怪留步，因攀桂丛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-2387aa85-45b4-4884-baf8-83de0d071285","tags":[]},{"id":"poem-9c7b2f769a0061eec21ef418","title":"送新罗僧","author":"张乔","dynasty":"唐","verses":["东来此学禅，多病念佛缘。","把锡离岩寺，收经上海船。","落帆敲石火，宿岛汲瓶泉。","永向扶桑老，知无再少年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f6d277af-3905-4a1b-98e9-7d57e4a64806","tags":[]},{"id":"poem-9c88e1ba12070bb3a16e700a","title":"漂母岸","author":"崔国辅","dynasty":"唐","verses":["泗水入淮处，南边古岸存。","秦时有漂母，于此饭王孙。","王孙初未遇，寄食何足论。","后为楚王来，黄金答母恩。","事迹遗在此，空伤千载魂。","茫茫水中渚，上有一孤墩。","遥望不可到，苍苍烟树昏。","几年崩冢色，每日落潮痕。","古地多陻圮，时哉不敢言。","向夕泪沾裳，遂宿芦洲村。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-24a802b4-2dfd-40c4-b656-a59bc27c1d30","tags":[]},{"id":"poem-9c962e2758ba1949b10af8cf","title":"得山中道友书寄苗銭二员外","author":"李端","dynasty":"唐","verses":["有谋皆𫐘轲，非病亦迟回。","壮志年年减，驰晖日日催。","还山不及伴，到阙又无媒。","高卧成长策，微官称下才。","诗人识何谢，居士别宗雷。","迹向尘中隐，书从谷口来。","药栏遭鹿践，涧户被猿开。","野鹤巢云窦，游龟上水苔。","新欢追易失，故思渺难裁。","自有归期在，劳君示劫灰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-18970206-4b28-4c5e-974f-a9ef44cbc9a7","tags":[]},{"id":"poem-9c9c04c59c1063e15d9a420a","title":"句","author":"卫填","dynasty":"唐","verses":["明月开时山夜白，暖泉流处草冬青。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2ddb256c-92da-46aa-85c0-a9dda021c6f6","tags":[]},{"id":"poem-9cad9f67ac9774c90a2f4eea","title":"七夕","author":"杨朴","dynasty":"宋","verses":["未会牵牛意若何，须邀织女弄金梭。","年年乞与人间巧，不道人间巧已多。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-七夕","tags":[]},{"id":"poem-9cb2df796d8d73ab0dbb6a3d","title":"贼警","author":"吕从庆","dynasty":"唐","verses":["兵火逾风疾，才西已及东。","苍翁灾海内，赤子哭途中。","城阙兼旬闭，邮书彻旦通。","不知调国者，何以慰时匆？"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e22dff99-7bf2-4587-a3c8-0d6849df25df","tags":[]},{"id":"poem-9cb9d50180f72f9444ce77ef","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["名园郡圃，是处秋千，花板争蹙。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2720","tags":[]},{"id":"poem-9cbe695866d5a1f8f1e9d1c2","title":"游璩源寺和韵","author":"柴元彪","dynasty":"宋","verses":["游人剔藓认坚珉，谁是开山第一人。","知有法𬤇留虎锡，元来璩叟是龙神。","云屏翠列悬崖树，雪瀑声飞断壑津。","又见生公重说法，祖师岩下草长春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-39a85205-b4a2-473a-8bbb-a28b98c8386f","tags":[]},{"id":"poem-9cc40cb6a5c6b09122b81858","title":"感遇十二首 一","author":"张九龄","dynasty":"唐","verses":["兰叶春葳蕤，桂华秋皎洁。","欣欣此生意，自尔为佳节。","谁知林栖者，闻风坐相悦。","草木有本心，何求美人折。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9b4f2d56-6df4-4999-a82c-11283529dd51","tags":["唐诗三百首","哲理","抒志","生活","五言古诗","植物"]},{"id":"poem-9cc5b891c04b255e6dffc997","title":"题襄阳图","author":"徐安贞","dynasty":"唐","verses":["画得襄阳郡，依然见昔游。","岘山思驻马，汉水忆回舟。","丹壑常含霁，青林不换秋。","图书空咫尺，千里意悠悠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4e35fd03-8317-42aa-8fde-a4f8171411a5","tags":[]},{"id":"poem-9cc8d5d594fc0a7510eddb2f","title":"克己复礼","author":"张载","dynasty":"宋","verses":["克己工夫未肯加，吝骄封闭缩如蜗。","试于中夜深思省，剖破藩篱即大家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ec038d85-3526-4f91-907f-ef67da77711b","tags":[]},{"id":"poem-9cd056e4807be6ccd77dc954","title":"句  其四","author":"许玠","dynasty":"宋","verses":["不办扁舟访安道。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-76a59bf3-c4f3-43db-9125-31fa5b92ee6d","tags":[]},{"id":"poem-9cd2b24bd9f6a18a0e1786df","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［末上］为功名纸半张，引得吾辈忙。","人人都想，要登龙虎榜。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8139","tags":[]},{"id":"poem-9cdbcde033a060461e821efe","title":"渔父·收却纶竿落照红","author":"纳兰性德","dynasty":"清","verses":["收却纶竿落照红，秋风宁为翦芙蓉。","人淡淡，水蒙蒙，吹入芦花短笛中。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-108","tags":[]},{"id":"poem-9ce9dbb2ac8717a90c0ba6ed","title":"华严真师以诗见贶聊成二章纪其趣尚  其一","author":"司马光","dynasty":"宋","verses":["知足随缘处处安，一身温饱不为难。","禅房窄小才容榻，此外从他世界寛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-e7060128-99d8-4587-883d-124aebb6bd7f","tags":[]},{"id":"poem-9cf449004fb957e3c6acf2a7","title":"奉和圣制南郊礼毕诗","author":"李德裕","dynasty":"唐","verses":["磬管歌大吕，冕裘旅天神。","烧萧辟阊阖，祈谷为蒸人。","羽旗洒轻雪，麦陇含阳春。","昌运岁今会，王猷从此新。","三臣皆就日，万国望如云。","仁寿信非远，群生方在钧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e7484e6e-8708-4236-824f-717093e5f953","tags":[]},{"id":"poem-9cf60623cf3a042590953c84","title":"哀倪孟容父词","author":"王柏","dynasty":"宋","verses":["忆昔见公兮，季原之堂。","兄弟怡怡兮，清约是将。","蔼子姓之弦歌兮，头角昂昂。","来者起敬兮，知德义之日昌。","造化无情兮，慨有季之先亡。","气象少异兮，灯火凄凉。","幸二子之自奋兮，视前有光。","何禄养之不久兮，遽惊风木之伤。","痛日月之未改兮，已变故常。","以公之刚介兮，岂北面于缁黄。","我知公之心兮，萦不足以挽其恨之长。","东风作恶兮雪絮正狂，黄垆晓启兮松楸苍苍。","劳生兮永佚，世事兮茫茫。","交之道兮日落，老有泪兮滂滂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-82e1ed4e-6bd5-4f2a-9d57-245e706e60df","tags":[]},{"id":"poem-9cfea6b2d824d1c190bb2d0a","title":"省试日上崔侍郎四首 三","author":"刘得仁","dynasty":"唐","verses":["戚里称儒媿小才，礼闱公道此时开。","他人何事虚相指，明主无私不是媒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-27ad0030-f8e6-4193-8ead-5cb8709856d6","tags":[]},{"id":"poem-9d0164c7df394dfbc50cfc2b","title":"和陈尉见贻二首  其二","author":"华镇","dynasty":"宋","verses":["燕语鶑啼次第新，柳绵花锦曲江滨。","且将邂逅天涯客，共看芳妍海角春。","须爱日添随日线，莫教花笑对花人。","一杯随分休辞诉，况有清歌激绛唇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-52321bd9-82f2-4bc5-9243-1d84fd2c2242","tags":[]},{"id":"poem-9d01a8b30614b6dccedbb3d9","title":"南有嘉鱼","author":"佚名","dynasty":"先秦","verses":["南有嘉鱼，烝然罩罩。君子有酒，嘉宾式燕以乐。","南有嘉鱼，烝然汕汕。君子有酒，嘉宾式燕以衎。","南有樛木，甘瓠累之。君子有酒，嘉宾式燕绥之。","翩翩者鵻，烝然来思。君子有酒，嘉宾式燕又思。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-170","tags":[]},{"id":"poem-9d02329dd17611655230ea70","title":"句","author":"李益","dynasty":"唐","verses":["闲庭草色能留马，当路杨花不避人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-37ab7b24-b25e-4492-88de-16a5eb4c2008","tags":[]},{"id":"poem-9d06277974397499fb09520e","title":"寒食二首 二","author":"李山甫","dynasty":"唐","verses":["风烟放荡花披猖，秋千女儿飞短墙。","绣袍驰马拾遗翠，锦袖鬬鸡喧广塲。","天地气和融霁色，池台日暖烧春光。","自怜尘土无他事，空脱荷衣泥醉乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-bc04b5a5-f7ea-4040-8872-19f2d1912c11","tags":[]},{"id":"poem-9d0733b2735b5eff63b22013","title":"帝京篇十首 二","author":"太宗皇帝","dynasty":"唐","verses":["岩廊罢机务，崇文聊驻辇。","玉匣启龙图，金绳披凤篆。","韦编断仍续，缥帙舒还卷。","对此乃淹留，欹案观坟典。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-13e72581-968b-457f-b381-a3b7d95b8b7c","tags":[]},{"id":"poem-9d0d3ae3a9bbc5498a637ea0","title":"采莲舞·蕊沼清冷涓滴水","author":"史浩","dynasty":"宋","verses":["蕊沼清冷涓滴水。","迢迢烟浪三千里。","微孕青房包绣绮。","薰风里。","幽芳洗尽闲桃李。","羽氅飘萧尘外侣。","相呼短棹轻偎倚。","一片清歌天际起。","声尤美。","双双惊起鸳鸯睡。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-5","tags":[]},{"id":"poem-9d10ee2e","title":"归园田居·其一","author":"陶渊明","dynasty":"晋","verses":["少无适俗韵，性本爱丘山。","误落尘网中，一去三十年。","羁鸟恋旧林，池鱼思故渊。","开荒南野际，守拙归园田。","方宅十余亩，草屋八九间。","榆柳荫后檐，桃李罗堂前。","暧暧远人村，依依墟里烟。","狗吠深巷中，鸡鸣桑树颠。","户庭无尘杂，虚室有余闲。","久在樊笼里，复得返自然。"],"enabled":true,"collection":"历代名篇","source":"《陶渊明集》诗《归园田居五首》其一。","tags":["田园","归隐"]},{"id":"poem-9d15fa36e6f6dba627cafd21","title":"钱塘江","author":"王镃","dynasty":"宋","verses":["凉丝疏柳条，秋满石阑桥。","吴越兴亡事，晨昏来去潮。","云开天日近，水接海山遥。","望到西陵渡，风帆影自飘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-559e78ae-c2d4-43bb-bfd1-e9add8c04a40","tags":["钱塘江"]},{"id":"poem-9d1ce5a393cb11eba47a0a94","title":"石榴花","author":"刘唐卿《白兔记》","dynasty":"元","verses":["我哥哥眼内识贤人，情愿将伊妹子结成亲。","他暂时落薄暂时贫，你们休得闲争论，被傍人闻知作话文。","大凡事须要相和顺。","刘郎发迹为官后，大家荣耀李庄门。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8855","tags":[]},{"id":"poem-9d1efd3f47a75ea84675bd4b","title":"登岳阳楼","author":"杜甫","dynasty":"唐","verses":["昔闻洞庭水，今上岳阳楼。","吴楚东南坼，乾坤日夜浮。","亲朋无一字，老病有孤舟。","戎马关山北，凭轩涕泗流。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-5d05fef6-e4aa-48e5-917d-c29d0e6d6b33","tags":["唐诗三百首","洞庭湖","岳阳楼","抱负","五言律诗","山水"]},{"id":"poem-9d1f8751960e7de68ebe484a","title":"米知县之官建平","author":"释居简","dynasty":"宋","verses":["凛然晋宋美风姿，又似君家古少仪。","剧县一经名辈作，春江相与白鸥宜。","盘根小试难藏利，剖竹乔迁勿复疑。","鸡犬相闻才隔岸，日边书到欲先知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-8aef9697-3d0b-4812-b7b3-22e1930fa2b5","tags":[]},{"id":"poem-9d294d2ae5f70fc425e59e74","title":"鼓吹曲辞 有所思","author":"韦应物","dynasty":"唐","verses":["借问江上柳，青青为谁春。","空游昨日地，不见昨日人。","缭绕万家井，往来车马尘。","莫道无相识，要非心所亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-95f31821-6665-4832-9780-ee1348df07cb","tags":[]},{"id":"poem-9d2b3beb17097741567dfe0a","title":"郊庙歌辞 梁太庙乐舞辞 帝盥","author":"不详","dynasty":"唐","verses":["庄肃莅事，周旋礼容。","裸鬯严洁，穆穆雍雍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-64e7b48a-305f-4d78-a810-c84a76b7b348","tags":[]},{"id":"poem-9d2dc12f96cc05895042c3cb","title":"偈 一","author":"师备","dynasty":"唐","verses":["三棒愚痴不思议，浩浩溶溶自打之。","行来目前明明道，七颠八倒是汝机。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d8498db1-4a8b-4b1d-a8e1-09a4ee9a2daa","tags":[]},{"id":"poem-9d2f396fd5427504e15f2017","title":"赠衡岳隐禅师","author":"李端","dynasty":"唐","verses":["旧住衡州寺，随缘偶北来。","夜禅山雪下，朝汲竹门开。","半偈传初尽，群生意未回。","唯当与樵者，杖锡入天台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-09e8939a-ce9c-42d6-b6d5-1d0ae752a3c6","tags":[]},{"id":"poem-9d2f8ecc0db25b61d46836dc","title":"草虫","author":"佚名","dynasty":"先秦","verses":["喓喓草虫，趯趯阜螽。未见君子，忧心忡忡。亦既见止，亦既觏止，我心则降。","陟彼南山，言采其蕨。未见君子，忧心惙惙。亦既见止，亦既觏止，我心则说。","陟彼南山，言采其薇。未见君子，我心伤悲。亦既见止，亦既觏止，我心则夷。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-13","tags":[]},{"id":"poem-9d3202ed5d8002d44cb9e7bc","title":"题汝坟驿壁三首  其一","author":"廖正一","dynasty":"宋","verses":["阿怜二十颇有余，秀眉丰颊冰琼肤。","无端欲作商人妇，更枉方寻海畔夫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-47b010b3-a163-4608-b68b-cf87b14135c5","tags":[]},{"id":"poem-9d427fd13a48673289556949","title":"送王炎弼赴山阳守以兵卫森画戟宴寝凝清香为韵十首  其八","author":"曾协","dynasty":"宋","verses":["疆事须长算，朝家得实能。","坐来酬万务，心地自虚凝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1bcec47c-9252-4322-b61d-a1eb1443e751","tags":[]},{"id":"poem-9d48c2b611abb58ca1396af5","title":"江西逢僧省文 二","author":"曹松","dynasty":"唐","verses":["高僧不负雪峰期，却伴青霞入翠微。","百叶岩前霜欲降，九枝松上鹤初归。","风生碧涧鱼龙跃，威振金楼燕雀飞。","想得白莲花上月，满山犹带旧光辉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ae603c61-4407-42e2-ac48-531173ad84d2","tags":[]},{"id":"poem-9d524355ad8c58a576d70d84","title":"蔷薇","author":"徐夤","dynasty":"唐","verses":["朝露洒时如濯锦，晚风飘处似遗钿。","重门剩著黄金锁，莫被飞琼摘上天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-cbd3dc1d-57f7-416d-898d-2a17500b8062","tags":[]},{"id":"poem-9d5605e51c3133bbb8d96916","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["风光正暮春，便纵然劳役，何必愁闷？绿英红雨，征袍上染惹芳尘。","云梯月殿图贵显，水宿风餐莫厌贫。","(合)乘桃浪，跃锦鳞，一声雷动过龙门。","荣归去，绿绶新，休教妻嫂笑苏秦。","(净唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4972","tags":[]},{"id":"poem-9d5cbc9f42d7d6d6d627753a","title":"句","author":"卢秀才","dynasty":"唐","verses":["长醉金陵前殿酒，偏闻玉树后庭花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0a3953f0-cfc3-4205-aef1-b0098d20153c","tags":[]},{"id":"poem-9d5f2f8b2d033850a2e194bf","title":"兔罝","author":"佚名","dynasty":"先秦","verses":["肃肃兔罝，椓之丁丁。赳赳武夫，公侯干城。","肃肃兔罝，施于中逵。赳赳武夫，公侯好仇。","肃肃免罝，施于中林。赳赳武夫，公侯腹心。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-6","tags":[]},{"id":"poem-9d5f6098a306731a456de685","title":"光光乍/同前","author":"萧德祥《小孙屠》","dynasty":"元","verses":["夫妻是宿缘，当与你作宛转。","放下心肠休忧虑，管教你成姻眷。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8587","tags":[]},{"id":"poem-9d62aacad9884e3ba6b88ff4","title":"病柏","author":"杜甫","dynasty":"唐","verses":["有柏生崇冈，童童状车盖。","偃蹙龙虎姿，主当风云会。","神明依正直，故老多再拜。","岂知千年根，中路颜色坏。","出非不得地，蟠据亦高大。","岁寒忽无凭，日夜柯叶改。","丹凤领九雏，哀鸣翔其外。","鸱鸮志意满，养子穿穴内。","客从何乡来，伫立久吁怪。","静求元精理，浩荡难倚赖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7b60930e-556e-433e-a978-8a175c33ee87","tags":[]},{"id":"poem-9d68247685b9dde1b799b13f","title":"锦衣香","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［末］夫性聪，才堪重；妇有容，德堪重，天生美质奇才，彩驾丹凤。","［生］自惭非是汉梁鸿，何当富室，配着孤穷。","［旦］念妾非孟光，奉亲命遣侍明公。","今日同欢共，蓝田玉曾修种。","夫和妇睦，琴调瑟弄。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8107","tags":[]},{"id":"poem-9d6f6c9559a66d0e9fa161fe","title":"桃花石枕歌送安吉康丞","author":"皎然","dynasty":"唐","verses":["君吏桃州尚奇迹，桃州采得桃花石。","烂疑朝日照已舒，含似春风吹未坼。","珪璋特达世所珍，吾知此物亦其伦。","应羡花开不凋悴，应嘉玉片无缁磷。","立性坚刚平若砥，君子偏将交道比。","何人亦秉坚刚姿，吾见君心得如此。","君心所好我独知，别多见少长相思。","从来赏玩安左右，万里提携君莫辞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-efea89d2-59ff-4599-af6d-a2801c8ff62e","tags":[]},{"id":"poem-9d80b4cc7142a6d839984f46","title":"宛丘","author":"佚名","dynasty":"先秦","verses":["子之汤兮，宛丘之上兮。洵有情兮，而无望兮。","坎其击鼓，宛丘之下。无冬无夏，值其鹭羽。","坎其击缶，宛丘之道。无冬无夏，值其鹭翿。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-135","tags":[]},{"id":"poem-9d876e44413ff36ae4229be1","title":"郊庙歌辞 祭汾阴乐章 凯安","author":"蒋挺","dynasty":"唐","verses":["维岁之吉，维辰之良。","圣君绂冕，肃事坛场。","大礼已备，大乐斯[张]。","神其醉止，降福无疆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e263b90b-b39e-4eb7-a648-5f7f2b74db68","tags":[]},{"id":"poem-9d8b9d2c2cd4358d4f884362","title":"灵台","author":"佚名","dynasty":"先秦","verses":["经始灵台，经之营之。庶民攻之，不日成之。经始勿亟，庶民子来。","王在灵囿，麀鹿攸伏。麀鹿濯濯，白鸟翯翯。王在灵沼，于牣鱼跃。","虡业维枞，贲鼓维镛。于论鼓钟，于乐辟雍。","于论鼓钟，于乐辟雍。鼍鼓逢逢。蒙瞍奏公。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-241","tags":[]},{"id":"poem-9d8f77f34541d95217fe54ea","title":"郊庙歌辞 五郊乐章 黄帝宫音 肃和","author":"魏征","dynasty":"唐","verses":["眇眇方舆，苍苍圜盖。","至哉枢纽，宅中图大。","气调四序，风和万籁。","祚我明德，时雍道泰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e9e9c629-6367-4dc1-a5fc-e2a45d02e122","tags":[]},{"id":"poem-9da354c1da71dcc57318cf5a","title":"更漏子·春夜阑","author":"毛文锡","dynasty":"五代","verses":["春夜阑，春恨切，花外子规啼月。","人不见，梦难见，红纱一点灯。","偏怨别，是芳节，庭中丁香千结。","宵雾散，晓霞晖，梁同双燕飞。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-10","tags":[]},{"id":"poem-9da724d5212d32bf3abb8648","title":"题济川亭","author":"释宗觉","dynasty":"宋","verses":["高亭窥绿润，古寺面苍阴。","闻有遗仙事，应容过客寻。","路危山背迥，云重洞天深。","一鸟不飞去，时能弄好音。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b12ad747-65e6-49ba-bdc7-269937071fb5","tags":[]},{"id":"poem-9daa49de30c8d9cf556b5814","title":"送僧清演归山","author":"李洞","dynasty":"唐","verses":["毛褐斜肩背负经，晓思吟入窦山青。","峰前野水横官道，踏着秋天三四星。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-841b15a6-0553-49ee-8de6-37ec9419c3b3","tags":[]},{"id":"poem-9dab3470a7ed98bcbe49bbff","title":"和叔崇清明后四绝  其四","author":"王柏","dynasty":"宋","verses":["缓步微吟竹一枝，情怀不比少年时。","少年春思无归宿，却是如今老会嬉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1be10fce-e0e8-43bb-90e4-b20a08088941","tags":[]},{"id":"poem-9dacc35299d5a3452dfda4b5","title":"端午","author":"明皇帝","dynasty":"唐","verses":["端午临中夏，时清日复长。","盐梅已佐鼎，曲糵且传觞。","事古人留迹，年深缕积长。","当轩知槿茂，向水觉芦香。","亿兆同归寿，群公共保昌。","忠贞如不替，贻厥后昆芳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6ac93ab8-f32b-49b6-8f72-938e414c9cca","tags":["端午节"]},{"id":"poem-9dbfb06eb9c7025685db7093","title":"春暮思平泉杂咏二十首 西园","author":"李德裕","dynasty":"唐","verses":["西园最多趣，永日自忘归。","石濑流清浅，风岑澹翠微。","晓翻红药艳，晴袅碧潭辉。","独望娟娟月，宵分半掩扉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-26fd6c50-4a0d-4358-ba54-5ff59e9d4d27","tags":[]},{"id":"poem-9dc5b843d0f435a45c603798","title":"东平路作三首 二","author":"高适","dynasty":"唐","verses":["明时好画策，动欲干王公。","今日无成事，依依亲老农。","扁舟向何处？吾爱汶阳中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a01fffef-b801-4397-958b-8435953a1802","tags":[]},{"id":"poem-9dd0f4d9cf0ab2373d199a64","title":"戏示语道","author":"刘跂","dynasty":"宋","verses":["御史青骢持望重，将军赤兔得勋多。","乘黄騕褭今相见，垓下乌骓奈若何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-81ef6f81-d538-40fa-9df3-fc2bf3cfa5f8","tags":[]},{"id":"poem-9ddcf384a979bdeca2260c1f","title":"观灯玉台体十首  其八","author":"徐铉","dynasty":"宋","verses":["星汉斜，乐无涯。","明月千门雪，银灯万树花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-53cd7671-2e3d-48f2-ac20-7b3a5d5a64c6","tags":[]},{"id":"poem-9de90f2d3550cb8bf72e86a1","title":"北山","author":"佚名","dynasty":"先秦","verses":["陟彼北山，言采其杞。偕偕士子，朝夕从事。王事靡盬，忧我父母。","溥天之下，莫非王土；率土之滨，莫非王臣。大夫不均，我从事独贤。","四牡彭彭，王事傍傍。嘉我未老，鲜我方将。旅力方刚，经营四方。","或燕燕居息，或尽瘁事国；或息偃在床，或不已于行。","或不知叫号，或惨惨劬劳；或栖迟偃仰，或王事鞅掌。","或湛乐饮酒，或惨惨畏咎；或出入风议，或靡事不为。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-204","tags":[]},{"id":"poem-9e07b3284440c4e918d0edf3","title":"杭州北郭戴氏荷池送侯愉","author":"崔国辅","dynasty":"唐","verses":["秋近万物肃，况当临水时。","折花赠归客，离绪断荷丝。","谁谓江国永，故人感在兹。","道存过北郭，情极望东菑。","乔木故园意，鸣蝉穷巷悲。","扁舟竟何待，中路每迟迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-91abfcf4-bf83-443d-976f-11f3b1b332f1","tags":[]},{"id":"poem-9e095b51a58461affd6a402a","title":"题金陵渡","author":"张祜","dynasty":"唐","verses":["金陵津渡小山楼，一宿行人自可愁。","潮落夜江斜月里，两三星火是瓜州。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-bce40ff4-816c-490c-be30-04de15f7c25e","tags":["唐诗三百首","抒情","七言绝句","旅途"]},{"id":"poem-9e0b6238f1993deee0c405dd","title":"买药歌送杨山人","author":"皎然","dynasty":"唐","verses":["华阴少年何所希，欲饵丹砂化骨飞。","江南药少淮南有，暂别胥门上京口。","京口斜通江水流，斐回应上青山头。","夜惊潮没鸬鹚堰，朝看日出芙蓉楼。","摇荡春风乱帆影，片云无数是扬州。","扬州喧喧卖药市，浮俗无由识仙子。","河间姹女直千金，紫阳夫人服不死。","吾于此道复何如，昨朝新得蓬莱书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-43cac04d-45ad-4a67-a715-f2d310cd6faa","tags":[]},{"id":"poem-9e0f4b980d9a42232e826a43","title":"马诗二十三首 十四","author":"李贺","dynasty":"唐","verses":["香襆赭罗新，盘龙蹙镫鳞。","回看南陌上，谁道不逢春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-cd42be7e-4ad9-4998-87a3-48dbbd9e6be8","tags":[]},{"id":"poem-9e11148d35f6eb23697538bd","title":"寿蔡大资","author":"华镇","dynasty":"宋","verses":["岩岩巨镇瞻维岳，落落乔松栋干姿。","物外风神时远鹤，几先识断世元龟。","还逢周寝占熊旦，恰是商岩肖象时。","愿酝东溟为寿酒，一年一献一瑶巵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-fa2491a4-635a-4bc6-b015-dea72ffa86c5","tags":[]},{"id":"poem-9e1632b4fe3ee373a185ef97","title":"纳凉","author":"王维","dynasty":"唐","verses":["乔木万余株，清流贯其中。","前临大川口，豁达来长风。","涟漪涵白沙，素鲔如游空。","偃卧盘石上，翻涛沃微躬。","漱流复濯足，前对钓鱼翁。","贪饵凡几许，徒思莲叶东。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4ba4b85f-3539-42c6-8cd7-c054d79b9331","tags":[]},{"id":"poem-9e19c44dd7b2a19fe164fd8f","title":"木兰花・玉楼春·池塘水绿风微暖","author":"晏殊","dynasty":"宋","verses":["池塘水绿风微暖。","记得玉真初见面。","重头歌韵响铮琮，入破舞腰红乱旋。","玉钩阑下香阶畔。","醉后不知斜日晚。","当时共我赏花人，点检如今无一半。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-164","tags":["宋词三百首"]},{"id":"poem-9e1b981d20449dc3199de175","title":"送裘父姪还乡二首  其二","author":"曾协","dynasty":"宋","verses":["尘外情怀得自由，便携琴鹤上归舟。","露寒月白关心夜，山瘦江清满意秋。","却背京城无眷恋，去寻古迹有迟留。","奚奴莫厌诗囊满，重纪山川烂漫游。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f0670456-8631-4faa-a4df-f438eb50e913","tags":[]},{"id":"poem-9e1d82963f13dbf14fea8c83","title":"南州行","author":"徐延寿","dynasty":"唐","verses":["摇艇至南国，国门连大江。","中洲西边岸，数步一垂杨。","金钏越溪女，罗衣胡粉香。","织缣春卷幔，采蕨暝提筐。","弄瑟娇垂幌，迎人笑下堂。","河头浣衣处，无数紫鸳鸯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-57f3cd85-28f7-47ba-accb-b9d2b7d10f1d","tags":[]},{"id":"poem-9e21b97f171bf2556f292e60","title":"东溪夜泊","author":"赵崇鉘","dynasty":"宋","verses":["雪满汀洲风满林，霁光空澈夜深深。","推篷恰受梅花月，自喷横箫调楚吟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-e98423f6-0aa4-44db-b633-315c7f5967ee","tags":[]},{"id":"poem-9e2d69b77288e8a93af8447f","title":"客中初夏","author":"司马光","dynasty":"宋","verses":["四月清和雨乍晴，南山当户转分明。","更无柳絮因风起，惟有葵花向日倾。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-客中初夏","tags":[]},{"id":"poem-9e2fe4ed","title":"敕勒歌","author":"佚名","dynasty":"北朝","verses":["敕勒川，阴山下。","天似穹庐，笼盖四野。","天苍苍，野茫茫，风吹草低见牛羊。"],"enabled":true,"collection":"历代名篇","source":"《乐府诗集》杂歌谣辞《敕勒歌》。","tags":["民歌","草原"]},{"id":"poem-9e331b115938c6b1bd494586","title":"殿中杨监见示张旭草书图","author":"杜甫","dynasty":"唐","verses":["斯人已云亡，草圣秘难得。","及兹烦见示，满目一凄恻。","悲风生微绡，万里起古色。","锵锵鸣玉动，落落群松直。","连山蟠其间，溟涨与笔力。","有练实先书，临池真尽墨。","俊拔为之主，暮年思转极。","未知张王后，谁竝百代则。","呜呼东吴精，逸气感清识。","杨公拂箧笥，舒卷忘寝食。","念昔挥毫端，不独观酒德。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-be5dacfb-7444-484e-96d8-66ff88e6f10a","tags":[]},{"id":"poem-9e372f3b4d97ab73eac4bbe5","title":"玉楼春·月照玉楼春漏促","author":"顾敻","dynasty":"五代","verses":["月照玉楼春漏促，飒飒风摇庭砌竹。","梦惊鸳被觉来时，何处管弦声断续。","惆怅少年游冶去，枕上两蛾攒细绿。","晓莺帘外语花枝，背帐犹残红蜡烛。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-46","tags":[]},{"id":"poem-9e3b6ea0413b8485ae5390f9","title":"清平乐·翠蛾雪柳","author":"史浩","dynasty":"宋","verses":["翠蛾雪柳。","鬓影春风透。","灯火千门辉绮绣。","移下一天星斗。","剩拚连夜欢游。","金波欲上迟留。","且看香梅影底，双鸾舞彻梁州。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-125","tags":[]},{"id":"poem-9e4600c45cf30608ab25bf42","title":"静夜思","author":"李白","dynasty":"唐","verses":["床前看月光，疑是地上霜。","举头望山月，低头思故乡。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ca2c489a-e433-4c0f-8248-77d354f0665e","tags":["唐诗三百首","新乐府辞","思乡","中秋","一年级上册","月亮","五言绝句","小学古诗"]},{"id":"poem-9e4b97237523d7389b88b76c","title":"青山","author":"米芾","dynasty":"宋","verses":["一园松竹冷阴森，犹得桓公叹可临。","却叵刘琨看左传，玉壶徒缺误雄心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-461a89e9-a21c-4809-98e3-42620ec64dd4","tags":[]},{"id":"poem-9e4c3fec57ba9e7ebe216f23","title":"琉璃灯中鱼子","author":"释居简","dynasty":"宋","verses":["玄珠透水明，玉𫚭弄晶晶。","跃碍冰痕薄，潜疑月色新。","器宏斯可乐，水浅易持盈。","归趁烧灯后，苹洲拍拍春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-e0d95bbd-c51f-4886-a9b5-d708dac7c02d","tags":[]},{"id":"poem-9e50cf1a1176bb78f6cf7eea","title":"南徐好·南徐好","author":"仲殊","dynasty":"宋","verses":["南徐好，多景在楼前。","京口万家寒食日，淮南千里夕阳天。","天际几重山。","莺啼处，人倚画阑干。","西寨烟深晴后色，东风春减夜来寒。","花满过江船。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-894","tags":[]},{"id":"poem-9e549397f18ea0684fd4e51c","title":"祭退之","author":"张籍","dynasty":"唐","verses":["呜呼吏部公，其道诚巍昂。","生为大贤姿，天使光我唐。","德义动鬼神，鉴用不可详。","独得雄直气，发为古文章。","学无不该贯，吏治得其方。","三次论诤退，其志亦刚强。","再使平山东，不言所谋臧。","荐待皆寒羸，但取其才良。","亲朋有孤稚，婚姻有办营。","如彼天有斗，人可为信常。","如彼岁有春，物宜得华昌。","哀哉未申施，中年遽殂丧。","朝野良共哀，矧于知旧肠。","籍在江湖间，独以道自将。","学诗为众体，久乃溢笈囊。","略无相知人，黯如雾中行。","北游偶逢公，盛语相称明。","名因天下闻，传者入歌声。","公领试士司，首荐到上京。","一来遂登科，不见苦贡场。","观我性朴直，乃言及平生。","由兹类朋党，骨肉无以当。","坐令其子拜，常呼幼时名。","追招不隔日，继践公之堂。","出则连辔驰，寝则对榻床。","搜穷古今书，事事相酌量。","有花必同寻，有月必同望。","为文先见草，酿熟偕共觞。","新果及异鲑，无不相待尝。","到今三十年，曾不少异更。","公文为时师，我亦有微声。","而后之学者，或号为韩张。","我官麟台中，公为大司成。","念此委末秩，不能力自扬。","特状为博士，始获升朝行。","未几享其资，遂忝南宫郎。","是事赖拯扶，如屋有栋梁。","去夏公请告，养疾城南庄。","籍时官休罢，两月同游翔。","黄子陂岸曲，地旷气色清。","新池四平涨，中有蒲荇香。","北台临稻畴，茂柳多阴凉。","板亭坐垂钓，烦苦稍已平。","共爱池上佳，联句舒遐情。","偶有贾秀才，来兹亦同幷。","移船入南溪，东西纵篙撑。","划波激船舷，前后飞鸥鸧。","回入潭濑下，网截鲤与鲂。","踏沙掇水蔬，树下烝新秔。","日来相与嬉，不知暑日长。","柴翁携童儿，聚观于岸傍。","月中登高滩，星汉交垂芒。","钓车掷长线，有获齐欢惊。","夜阑乘马归，衣上草露光。","公为游谿诗，唱咏多慨慷。","自期此可老，结社于其乡。","籍受新官诏，拜恩当入城。","公因同归还，居处隔一坊。","中秋十六夜，魄圆天差晴。","公既相邀留，坐语于堦楹。","乃出二侍女，合弹琵琶筝。","临风听繁丝，忽遽闻再更。","顾我数来过，是夜凉难忘。","公疾浸日加，孺人视药汤。","来候不得宿，出门每回遑。","自是将重危，车马候纵横。","门仆皆逆遣，独我到寝房。","公有旷达识，生死为一纲。","及当临终晨，意色亦不荒。","赠我珍重言，傲然委衾裳。","公比欲为书，遗约有修章。","令我署其末，以为后事程。","家人号于前，其书不果成。","子符奉其言，甚于亲使令。","鲁论未讫注，手迹今微茫。","新亭成未登，闭在庄西厢。","书札与诗文，重叠我笥盈。","顷息万事尽，肠情多摧伤。","旧茔盟津北，野窆动鼓钲。","柳车一出门，终天无回箱。","籍贫无赠赀，曷用申哀诚。","衣器陈下帐，醪饵奠堂皇。","明灵庶鉴知，髣髴斯来飨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7798a85b-ae35-4abc-bfb7-1c43940b2de2","tags":[]},{"id":"poem-9e570d124a9ede4cc9e16a7e","title":"题玄哲禅师影堂","author":"张乔","dynasty":"唐","verses":["吾师视化身，一念即遗尘。","岩谷藏虚塔，江湖散学人。","云迷禅处石，院掩写来真。","寂寞焚香后，闲阶细草生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-04e0ba93-51db-4633-8b0e-91127e8be054","tags":[]},{"id":"poem-9e5a34c99522bd3d23e0c04a","title":"辋川集 鹿柴","author":"王维","dynasty":"唐","verses":["空山不见人，但闻人语响。","返景入深林，复照青苔上。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2e8999a9-9df8-4483-ab1e-0231c3e46320","tags":["唐诗三百首","写景","山","描写山","写山","五言绝句"]},{"id":"poem-9e5e9da99cd4d1cebde04dfb","title":"江行无题一百首 四十六","author":"钱珝","dynasty":"唐","verses":["土旷深耕少，江平远钓多。","平生皆弃本，金革竟如何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3a2152cb-d73f-4ac5-9bc0-69b2b0685cbd","tags":[]},{"id":"poem-9e5f5d155baa97327d86655c","title":"萤","author":"徐夤","dynasty":"唐","verses":["月坠西楼夜影空，透帘穿幕达房栊。","流光堪在珠玑列，为火不生榆柳中。","一一照通黄卷字，轻轻化出绿芜丛。","欲知应候何时节，六月初迎大暑风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ba1b61cb-3102-490f-babe-eca519dd4aed","tags":[]},{"id":"poem-9e607873cf361e77da51d3d1","title":"别陈给事诸公赴陆府判盘隠之约","author":"释居简","dynasty":"宋","verses":["挂包妃子墓田居，余地无钱买一鉏。","隣寺笑贫稀住计，孤山嫌怪索离书。","鸿虽自去何须送，鸥不曾亲尽不疎。","亟欲寄声寻便武，只烦三十六鳞鱼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9397a701-f11e-4ed9-b1aa-ed730f490725","tags":[]}];
